 if(!r.ok||data.error)throw Object.assign(new Error(data.error||'連線失敗'),{authExpired:r.status===401||data.code==='AUTH_EXPIRED'||/(?:裝置)?登入已到期|MEMBERSHIP_|ACCOUNT_DISABLED|SESSION_ACCOUNT_MISMATCH/.test(data.error||'')});
