async function loadCommonBook(page=0){if(route!=='common-book')return;const generation=++commonBook.generation;commonBook.page=Math.max(0,page);commonBook.loading=true;renderCommonBook();if(demo){commonBook.rows=[];commonBook.total=0;commonBook.loading=false;renderCommonBook();return;}try{const response=await api({op:'catalogSongbook',q:commonBook.q,language:commonBook.language,performerType:commonBook.performerType,versionKind:commonBook.versionKind,versionLabel:commonBook.versionLabel,sort:commonBook.sort,limit:12,offset:commonBook.page*12});if(generation!==commonBook.generation)return;commonBook.rows=response.rows||[];commonBook.total=response.total||0;if(response.filters)commonBook.options={languages:response.filters.languages||[],performerTypes:response.filters.performerTypes||[],versionKinds:response.filters.versionKinds||[],versionLabels:response.filters.versionLabels||[]};commonBook.error='';}catch(err){if(generation!==commonBook.generation)return;commonBook.error=err.message;commonBook.rows=[];}finally{if(generation===commonBook.generation){commonBook.loading=false;renderCommonBook();}}}
