function ledgerRows(id,manager){let rows=state.ledger.filter(l=>(!id||l.playerId===id)&&venuePolicyLedgerPool(l)===venuePolicySettings(state.settings).current_space);if(!id&&ledgerQuery){const ids=playerSearch(state,ledgerQuery,true).map(x=>x.playerId);rows=rows.filter(l=>ids.includes(l.playerId));}rows.sort((a,b)=>(timeValue(b.at)||0)-(timeValue(a.at)||0));const p=paginate(rows,'ledger');return `${manager?`<div class="toolbar">${venueSwitch()}${!id?`<input id="ledger-query" value="${h(ledgerQuery)}" placeholder="搜尋玩家名稱、ID、曾用名" aria-label="存歌玩家搜尋">`:''}${button('新增存歌','addLedger',id||'')}</div><small>最近 · 每頁 10 筆</small>`:''}<div id="ledger-results">${p.rows.map(l=>`<div data-ledger-id="${h(l.id)}" class="song admin-row"><div class="info"><b>${manager?h(playerName(l.playerId))+' · ':''}<span class="${l.amount>=0?'positive':'negative'}">${l.amount>=0?'+':''}${l.amount} 首</span></b><small>${time(l.at)} · ${h(l.note)}${l.voided_at?' · 僅保留紀錄':l.reversal_of?' · 關聯回補':l.accounting_adjustment?' · 人工補正':''}${venuePolicySettings(state.settings).radio_enabled?' · '+venueName(venuePolicyLedgerPool(l)):''}</small></div>${manager?`<div class="actions">${(l.allocationSettlement||l.queueId||l.reversal_of||l.voided_at)?'':button('編輯','editLedger',l.id)}${l.amount>0&&!l.queueId&&!l.conversion&&!l.voided_at&&!l.allocation_id&&!l.accounting_adjustment?button('分配','allocate',l.id):''}${l.allocationSettlement||l.queueId||l.reversal_of||l.voided_at?'':button('撤銷','deleteLedger',l.id,'tiny danger')}</div>`:''}</div>`).join('')||blank()}${p.nav}</div>`;}
function queueRows(rows,manager,compact=true,history=false,showSort=true,sortCurrent=!manager){const sortKey=history?'queueHistory':'queueCurrent';if(history||sortCurrent)rows=[...rows].sort((a,b)=>(listSorts[sortKey]==='oldest'?1:-1)*(timeValue(history?a.effective_at||a.completedAt||a.at:a.at)-timeValue(history?b.effective_at||b.completedAt||b.at:b.at)));const p=paginate(rows,history?'queue-history':'queue');return (showSort&&history?sortControl(sortKey):'')+p.rows.map(q=>{const active=['waiting','pending'].includes(q.status),confirmed=queueConfirmed(q),prepared=queuePrepared(q),title=q.items?.map(i=>i.title+(i.performances>1?' ×'+i.performances:'')).join(' ＋ ')||q.title,artist=q.artist||[...new Set((q.items||[]).map(i=>i.artist).filter(Boolean))].join('／')||song(q.songId)?.artist||'';const lyricItems=q.items?.length?q.items:[q],hasLyrics=lyricItems.some(i=>{const row=song(i.songId);return !!(row?.hasLyrics??String(row?.lyrics||'').trim());});const primary=!active?'':q.status==='pending'?button('確認禮物','queueOp',q.id,'primary','data-op="approve"'):q.awaitingAcknowledgment?button('確認收到','queueOp',q.id,'primary','data-op="acknowledge"'):q.awaitingPreparation?button('設定準備時間','stage',q.id,'primary'):q.status==='waiting'?button('🎤 完成演唱','queueOp',q.id,'primary','data-op="complete"'):'';return `<article data-queue-id="${h(q.id)}" class="song admin-row queue-row ${manager?'queue-manager-view':'queue-player-view'} ${compact?'queue-compact':''}">${manager?'<input type="checkbox" aria-label="選取 '+h(q.title)+'" data-queue-select="'+h(q.id)+'" '+(selectedQueue.has(q.id)?'checked':'')+'>':''}<div class="info">${compact?`<div class="queue-track"><b class="queue-title">${h(title)}</b><span class="queue-artist">${artist?h(artist):''}</span></div>`:`<b class="queue-title">${h(title)}</b><span class="queue-artist">${h(artist)}</span><strong class="queue-player">${h(q.kind==='self'?'主播自帶':playerName(q.playerId))}</strong>`}<small class="queue-meta" title="${h(q.requestNote||'')}"><span class="queue-state" data-preparation="${h(q.id)}">${active?h(queuePreparation(q,clock())):statusName[q.status]}</span> · ${compact&&manager?`<strong class="queue-player">${h(q.kind==='self'?'主播自帶':playerName(q.playerId))}</strong> · `:''}${q.kind==='self'?'主播自帶':q.kind==='saved'?'提歌':'現點'} · <time class="queue-time">${time(q.effective_at||q.completedAt||q.at)}</time>${venuePolicyHistoryVenue(q)?' · '+venueName(q.venue):''}${q.selfProvided?' · '+h(requestSourceLabel(q)):''}${q.quota_carried===true?' · 已過檔':''}${q.archived_at?' · 已封存':''}${q.performance_duplicate_of?' · 僅保留紀錄':''}${q.test?' · 測試':''}${q.requestNote&&compact?'<span class="queue-request-note" aria-label="玩家留言" title="'+h(q.requestNote)+'"> 💬'+(!manager?' '+h(q.requestNote):'')+'</span>':''}</small>${q.requestNote&&!compact?'<small class="queue-request-note">💬 '+h(q.requestNote)+'</small>':''}</div>${manager?'<div class="queue-controls"><div class="queue-primary">'+primary+'</div>'+'<details class="queue-more"><summary>更多</summary><div class="queue-more-content">'+(prepared?'<div class="queue-secondary">'+(hasLyrics?button('查看歌詞','queueLyrics',q.id):'')+button('編輯／換歌','editQueue',q.id)+button('準備時間','stage',q.id)+'</div>':'')+(!active&&hasLyrics?button('查看歌詞','queueLyrics',q.id):'')+(active?button('取消','queueOp',q.id,'tiny','data-op="cancel"'):'')+(prepared?button('↑','move',q.id,'tiny','data-step="-1"')+button('↓','move',q.id,'tiny','data-step="1"')+(q.kind==='live'?button('未唱→存歌','queueOp',q.id,'tiny','data-op="store"'):''):'')+button(active?'時間／備註':'修改時間','recordTime',q.id,'tiny','data-table="queue"')+(q.allocation_id&&!active?'':button(active?'移出待播':'移除紀錄','queueOp',q.id,'tiny danger','data-op="delete"'))+(q.kind==='saved'?'<small>扣存歌來源：'+venueName(venuePolicyConsumedPool(q))+'</small>':q.allocation_id?'<small>分配存歌來源：'+venueName(q.allocation_storage_pool||'shengma')+'</small>':'')+(q.requestNote?'<p>玩家留言：'+h(q.requestNote)+'</p>':'')+(q.note?'<p>備註：'+h(q.note)+'</p>':'')+'</div></details></div>':active&&q.playerId===session?.playerId?button('取消','cancelOwn',q.id,'tiny queue-own-cancel'):''}</article>`;}).join('')+p.nav;}
function prepareQueue(id,operation){const q=state.queue.find(q=>q.id===id);if(!q)return;modal(operation==='approve'?'確認禮物 · 準備時間':operation==='acknowledge'?'確認收到 · 準備時間':'設定準備時間','<h3>'+h(q.title)+'－'+h(q.artist)+'</h3>'+field('preparationMinutes','準備時間（分鐘）',q.preparationMinutes??0,'number','min="0" max="120" step="1" required')+'<p>0 分鐘＝已準備好，立即通知玩家；1～120 分鐘會顯示倒數，到時通知玩家。</p>',async f=>dispatch('queue',{id,operation,preparationMinutes:f.get('preparationMinutes')}));}

function wishRows(rows,manager){const p=paginate(rows,'wishes');return p.rows.map(w=>`<div class="song" data-wish-id="${h(w.id)}"><div class="info"><b>${h(w.title)}－${h(w.artist)}</b><small>${manager?h(playerName(w.playerId))+' · ':''}${time(w.at)} · ${h(w.note)}</small><div class="tag">${h(w.status)}</div>${w.status==='已學會'?'<p class="positive">✨ 願望成真！這首'+h(hostName())+'學會啦～</p>':''}${w.url?`<a href="${h(w.url)}" target="_blank" rel="noopener">歌曲連結 ↗</a>`:''}</div>${manager?button('處理','editWish',w.id)+button('時間','recordTime',w.id,'tiny','data-table="wishes"'):''}</div>`).join('')+p.nav;}
const adminTabs=[['queue','🎤 待播'],['songs','🎵 歌本'],['players','👤 玩家'],['ledger','💾 存歌'],['crowns','👑 冠歌'],['cards','🖼️ 卡片'],['wishes','🌟 許願池'],['stats','📈 統計'],['events','📜 操作歷史'],['medals','🏅 勳章管理'],['settings','⚙️ 設定']];

function managementPage(){return route==='admin'&&tab==='platform'||route==='center'&&subtab==='platform';}
const managementEntry=createManagementEntry({api:b=>api({...b,platformSession:true}),identity:()=>admin||session,changed:()=>{if(managementPage())render();else if(managementEntry.state().ready)header();}});
const platformDirectory=createPlatformManagement({api:b=>api({...b,platformSession:true}),identity:()=>managementEntry.identity(),capabilities:()=>managementEntry.state().capabilities||{},escape:h,changed:()=>{if(managementPage())render();}});
function renderPlatformManagement(){
 if(!document.getElementById('platform-management-styles')){const css=document.createElement('link');css.id='platform-management-styles';css.rel='stylesheet';css.href=new URL('./platform-management.css?v=10.26-ADMIN.1',import.meta.url).href;document.head.append(css);}
 const access=managementEntry.state();
 if(!access.ready){$('#app').innerHTML=card('平台管理中心',access.error?'<p role="alert">'+h(access.error)+'</p>'+button('重新確認權限','platformOpen'):'<p role="status">確認管理權限中…</p>',true);if(!access.loading&&!access.error)void managementEntry.load();return;}
 if(!access.capabilities?.president){$('#app').innerHTML=card('平台管理中心','<p>此頁僅供總裁帳號使用，主播請使用自己的後台。</p>'+button('返回首頁','home'),true);return;}
 $('#app').innerHTML=button('返回首頁','home')+platformDirectory.html();platformDirectory.bind($('#app'));const p=platformDirectory.state();if(!p.loaded&&!p.loading&&!p.error)void platformDirectory.load();
}
async function openPlatformManagement(){if(!admin&&!session)throw Error('請先登入');const capabilities=await managementEntry.load({force:true});if(!capabilities?.president)throw Error(managementEntry.state().error||'平台管理中心僅供總裁帳號使用');if(isSuperAdmin()){route='admin';tab='platform';}else{route='center';subtab='platform';}syncPageLocation(true);render();}

function renderAdmin(){if(tab==='platform'){if(!document.getElementById('platform-management-styles')){const css=document.createElement('link');css.id='platform-management-styles';css.rel='stylesheet';css.href=new URL('./platform-management.css?v=10.26-ADMIN.1',import.meta.url).href;document.head.append(css);}if(!isSuperAdmin()){tab='queue';}else{$('#app').innerHTML=button('返回主播管理','adminTab','queue')+platformDirectory.html();platformDirectory.bind($('#app'));const p=platformDirectory.state();if(!p.loaded&&!p.loading&&!p.error)void platformDirectory.load();return;}}if(tab==='dashboard')tab='queue';let body='';
 if(tab==='queue')body=`<div class="queue-heading"><h2>🎤 待播</h2><div class="queue-live-tools">${venueSwitch()||button('啟用電台','editVenue')}<div class="live-shortcuts">${[['空閒','空閒中','#79d5b0'],['忙碌','忙碌中','#f299ab'],['準備','準備中','#e9b975'],['暫停','暫停點歌','#c4a5ed']].map(([label,value,color])=>button('<span class="queue-status-dot" aria-hidden="true" style="background:'+color+'"></span>'+label,'status',value,state.settings.status===value?'tiny active':'tiny')).join('')}</div></div></div><div class="queue-toolbar">${button('＋ 加入待播歌曲','onBehalf','','tiny primary queue-add')}<div class="tabs">${button('待播','queueMode','active',!queueHistory?'active':'')}${button('歷史','queueMode','history',queueHistory?'active':'')}</div></div><details class="queue-bulk"><summary>批次操作</summary>${button('全選目前列表','selectQueue')}${button('取消選取','clearQueueSelection')}${button('刪除已選','deleteSelectedQueue','','tiny danger')}</details>${queueRows(state.queue.filter(q=>queueHistory?!['pending','waiting'].includes(q.status):['pending','waiting'].includes(q.status)),true,true,queueHistory)}<footer class="queue-summary">${(()=>{const totals=currentAccounting();if(!totals)return blank('帳務摘要尚未確認');return `<div class="queue-totals">收到新歌 ${totals.received} 首 ｜ 存歌 ${totals.stored} 首 ｜ 已唱 ${totals.sung} 首</div>`;})()}<small>歌曲 ${state.songs.length} · 玩家 ${state.players.length} · 冠歌 ${state.crowns.length}</small></footer>`;

 if(tab==='songs')body=songToolbar(true)+songStatusToolbar()+`<details class="tag-management"><summary>管理本主播標籤</summary><div class="chips">${state.settings.tags.map(t=>button(h(t)+' ×','deleteTag',t)).join('')}${button('＋標籤','addTag')}</div></details><div id="song-batch-bar">${songBatchBar()}</div><div id="song-list">${adminSongList()}</div>`;
 if(tab==='players'){if(selectedPlayer)body=button('← 玩家列表','backPlayers')+playerTabs(selectedPlayer,true);else body='<div id="player-management">'+playerManagementPanel()+'</div>';}
 if(tab==='medals')body='<div id="medal-management">讀取勳章管理中…</div>';
 if(tab==='ledger')body=ledgerRows(null,true);
 if(tab==='crowns')body=`<div class="toolbar">${button('新增冠歌','editCrown')}${button('批量匯入','import','crowns')}${button('如何冠歌？','crownHelp')}</div>${crownsHtml(state.crowns,true)}`;
 if(tab==='cards')body=`<div class="toolbar">${button('上傳卡片','editCard')}</div><div class="gallery">${orderedCards(state.cards).map(c=>`<div>${photoHtml(c)}${button('↑','cardMove',c.id,'tiny','data-direction="-1" aria-label="卡片上移"')}${button('↓','cardMove',c.id,'tiny','data-direction="1" aria-label="卡片下移"')}${button('編輯','editCard',c.id)}${button('刪除','deleteCard',c.id,'tiny danger')}</div>`).join('')||blank()}</div>`;
 if(tab==='wishes')body=wishRows(state.wishes,true);
 if(tab==='activity')body=isSuperAdmin()?'<h2>玩家最近活動</h2><div id="activity-panel">讀取中…</div>':blank('只有 PA Party總裁可查看');
 if(tab==='stats')body=`<label>帳務日期<input id="stats-day" type="date" value="${accountingDay(clock(),accountingRollover(state))}"></label><div id="stats-result">${statsHtml(currentAccounting())}</div><p class="muted">依本 Space 設定換場。收到新歌不含分配退回；存歌為本場收到後未分配、未唱掉的首數；已唱包含提歌、現點及已過檔演唱。測試資料不列入。</p>`;
 if(tab==='events'){body='<p class="muted">重要操作永久保留，依登記時間由新到舊。可展開核對修改前後資料。</p><div id="event-list">讀取中…</div>';setTimeout(loadEvents,0);}if(tab==='settings')body=settingsHtml();
 if(tab==='catalog'&&admin){if(!isSuperAdmin()&&!['approved','issues'].includes(catalogView.section))catalogView.section='approved';body=catalogReviewHtml();}
 $('#app').innerHTML=`<div class="admin-banner"><b>🔐 ${isSuperAdmin()?'PA Party總裁 · ':''}${h(hostName())}的管理後台</b><div class="actions">${button(h('回'+hostName()+'首頁'),'home')}${button('修改密碼','changeManagerPassword')}${button('登出管理','adminLogout')}</div></div><div class="streamer-toolbar"><details class="room-picker"><summary>目前管理主播：${h(state.currentStreamer.display_name)}</summary><input type="search" data-room-filter placeholder="搜尋主播"><div class="room-options">${state.streamers.map(r=>button(h(r.display_name)+(r.active?'':'（未開放）'),'switchStreamer',r.slug)).join('')}</div></details>${isSuperAdmin()?'<details class="streamer-management-tools"><summary>平台管理</summary><div class="actions">'+button('平台管理中心','adminTab','platform')+'</div></details>':''}</div><div class="tabs admin-section-tabs" aria-label="管理功能">${adminTabs.slice(0,4).map(([id,label])=>button(label+(id==='wishes'&&state.wishes.some(w=>w.status==='收到')?' <span class="notice-count">'+Math.min(99,state.wishes.filter(w=>w.status==='收到').length)+'</span>':''),'adminTab',id,tab===id?'active':'')).join('')}${button('共同曲庫','adminTab','catalog',tab==='catalog'?'active':'')}<details class="admin-more-tabs ${adminTabs.slice(0,4).some(([id])=>id===tab)||tab==='catalog'?'':'active'}"><summary>更多<span class="menu-pending-dot" data-admin-more-alert data-local-pending="${state.wishes.filter(w=>w.status==='收到').length}" ${(state.wishes.some(w=>w.status==='收到')||notifications.systemUnread?.())?'':'hidden'} aria-label="有待處理或未讀事件"></span></summary><div class="admin-more-options">${[...adminTabs.slice(4),...(isSuperAdmin()?[['platform','平台總管理'],['activity','最近活動']]:[])].map(([id,label])=>button(label+(id==='wishes'&&state.wishes.some(w=>w.status==='收到')?' <span class="notice-count">'+Math.min(99,state.wishes.filter(w=>w.status==='收到').length)+'</span>':''),'adminTab',id,tab===id?'active':'')).join('')}</div></details></div><section class="card">${body}</section>`;if(!isSuperAdmin()){for(const el of document.querySelectorAll('[data-act=editStreamer],[data-act=draft],[data-act=publish],[data-act=backup],[data-act=migrate],[data-act=import][data-id=players]'))el.remove();document.querySelector('.room-picker')?.remove();}if(tab==='catalog'&&!catalogView.loaded&&!catalogView.loading)setTimeout(loadCatalogReview,0);
}
function editHome(){openHomeEditor({home:state.settings.home,room:state.currentStreamer,modal,dispatch,demo,toast,upload:async file=>(await api({op:'upload',image:await compress(file,1800),mime:'image/webp'})).url});}
// A published theme (首頁主題設計) wins; otherwise the earlier home colour settings apply unchanged.
function applyHomeTheme(){const root=document.documentElement;if(state.settings.theme){themeApply(root,state.settings.theme);return;}themeClear(root);if(!state.settings.home){delete root.dataset.homeTheme;return;}root.dataset.homeTheme='custom';for(const [k,v] of Object.entries(themePalette(state.settings.home.color,state.settings.home.themeColors)))root.style.setProperty('--home-'+k,v);}
// Decorations only on the streamer homepage; other pages inherit colours and images only.
function syncThemeDecor(){const app=$('#app'),theme=state.settings.theme,home=!['admin','common-book','book','center','gallery'].includes(route);if(!app)return;app.querySelector(':scope>.theme-decor-layer')?.remove();const html=home&&theme?themeDecorHtml(theme,{escape:h}):'';app.classList.toggle('theme-home-host',!!html);if(html)app.insertAdjacentHTML('beforeend',html);}
async function loadThemeStudio(){if(!document.querySelector('link[data-theme-studio-css]')){const link=document.createElement('link');link.rel='stylesheet';link.href=new URL('./theme-studio.css?v=10.28-THEME.3',import.meta.url).href;link.dataset.themeStudioCss='';document.head.append(link);}return import('./theme-studio.js?v=10.28-THEME.3');}
async function openThemeDesigner(){
 if(demo||draft)throw Error('首頁主題設計請在正式同步模式使用');if(!admin)throw Error('請先登入管理');
 const {openThemeStudio}=await loadThemeStudio();const room=state.currentStreamer,space=state.streamers.find(r=>r.id===room.id)?.spaceId||room.spaceId||'space-001';
 openThemeStudio({api,room,settings:state.settings,toast,songs:state.songs.filter(s=>!s.hidden).slice(0,6),hallName:'聲瑪',
  defaultBanner:state.settings.home?.imageMode==='custom'?state.settings.home.imageUrl:state.settings.home?.imageMode==='none'?'':room.banner_url||(streamerSlug==='papa'?'assets/papa-singer-hero.jpg':''),
  streamerNames:state.streamers.filter(r=>r.active&&(r.spaceId||'space-001')===space).map(r=>r.display_name),
  saveStreamer:payload=>dispatch('settings',payload),onClose:()=>render()});
}
async function openThemePlans(){
 if(!isSuperAdmin())throw Error('僅限 PA Party總裁');
 const {THEME_PLANS,THEME_STREAMER_FEATURES,THEME_HALL_FEATURES,THEME_FEATURE_LABELS}=await import('./theme-access.js?v=10.28-THEME.3');
 const r=await api({op:'themePlans',streamer:state.currentStreamer.id,management:true}),plan=r.plan||{},checks=(name,keys,on)=>keys.map(k=>`<label class="check-row"><input type="checkbox" name="${name}" value="${k}" ${on.includes(k)?'checked':''}> ${h(THEME_FEATURE_LABELS[k])}</label>`).join('');
 modal('會員方案與主題授權・'+state.currentStreamer.display_name,`<p class="muted">由總裁手動設定；不顯示、不儲存任何價格。主題功能目前生效：${r.effective.length?r.effective.map(k=>h(THEME_FEATURE_LABELS[k])).join('、'):'未開放'}</p>
 <label>會員方案<select name="plan"><option value="" ${plan.plan?'':'selected'} disabled>尚未設定（主題功能不開放）</option>${THEME_PLANS.map(([id,label])=>`<option value="${id}" ${plan.plan===id?'selected':''}>${h(label)}</option>`).join('')}</select></label>
 <label>狀態<select name="status"><option value="active" ${plan.status!=='suspended'?'selected':''}>啟用</option><option value="suspended" ${plan.status==='suspended'?'selected':''}>暫停</option></select></label>
 <label>有效期限（留空為不限期）<input type="date" name="validUntil" value="${h(plan.valid_until?String(plan.valid_until).slice(0,10):'')}"></label>
 <fieldset><legend>單項授權（「基本免費＋單項」與「免費歌本」方案才需要勾選）</legend>${checks('features',THEME_STREAMER_FEATURES,plan.features||[])}</fieldset>
 <fieldset><legend>此主播所屬廳的廳首頁主題授權</legend>${checks('hall',THEME_HALL_FEATURES,r.hallFeatures||[])}</fieldset>
 <p class="subtle">六位永久免費全功能主播請設為「終身免費全功能」；以複製主播建立的新主播不會自動繼承。</p>`,async f=>{
  await api({op:'themePlans',streamer:state.currentStreamer.id,save:true,management:true,plan:{plan:f.get('plan'),status:f.get('status'),validUntil:f.get('validUntil')||null,features:f.getAll('features')},hallFeatures:f.getAll('hall')});toast('會員方案與主題授權已儲存');
 });
}
function settingsHtml(){return `<div class="notice ${draft?'warning':''}">${demo?'預覽測試：資料只存在這台裝置':draft?'📝 草稿模式：只存在這台裝置':'☁️ 正式同步模式'}</div><div class="actions">${button('開始草稿測試','draft')}${button('匯出備份','backup')}${draft?button('正式同步','publish','','primary')+button('離開草稿','leaveDraft'):''}</div><hr><h3>專屬網址與 QR Code</h3><p class="muted">設定自己的公開首頁網址，複製或下載官方 LOGO QR Code。</p>${button('專屬網址與 QR Code','publicLinkSettings')}${isSuperAdmin()?button('大廳網址設定','publicHallSettings'):''}<hr><h3>首頁外觀與內容</h3><p class="muted">主題色、主圖、卡片顯示與排序、本日狀態欄位</p>${button('自訂首頁','editHome','','primary')}<hr><h3>🎨 首頁主題設計</h3><p class="muted">一次設計首頁，歌本、玩家頁與後台自動套用。可選主色一鍵配色、上傳背景／橫幅／卡片底圖／裝飾，手機即時預覽，草稿與發布分開。${state.settings.theme?'目前已發布主題，配色以主題為準。':''}</p>${button('首頁主題設計','themeStudio','','primary')}${isSuperAdmin()?button('會員方案與主題授權','themePlans'):''}<hr><h3>📻 電台設定</h3><p class="muted">${state.settings.radio_enabled===true?'已啟用 · 目前場域：'+venueName(venuePolicySettings(state.settings).current_space):'尚未啟用'}</p>${button('電台開關與場域','editVenue')}<hr><h3>直播與價格</h3><p class="muted">${h(state.settings.opening)} · 試音 ${money(state.settings.audition)} · 一般現點 ${money(state.settings.livePrice)}＋雙費 ${money(state.settings.liveDouble)}</p>${button('編輯設定與說明書','editSettings')}${button('存歌方案','editPlans')}${button('冠歌卡別價格','editTiers')}${isSuperAdmin()?'<hr><h3>系統工具／資料檢查</h3>'+button(catalogView.scanning?'掃描中…':catalogView.scanComplete?'重新掃描既有歌本':catalogView.scanCursor?'掃描下一批 100 首':'掃描既有歌本候選','catalogScan','','tiny',catalogView.scanning?'disabled':'')+'<p class="muted">已檢查 '+catalogView.scanTotal+' 首'+(catalogView.scanComplete?'，本輪完成':'；每批最多 100 首，只建立待審候選。')+'</p>'+(state.schemaVersion<3?button('讀取舊版資料並核對','migrate'):'')+(state.migrationIssues?.length?'<details class="notice warning"><summary>資料移轉待核對 '+state.migrationIssues.length+' 項</summary>'+state.migrationIssues.map(h).join('<br>')+'</details>':'<small>沒有待核對的舊版資料</small>'):''}`;}
function render(){managementEntry.sync();platformDirectory.sync();if(!demo&&(admin||session)){const entry=managementEntry.state();if(!entry.ready&&!entry.loading&&!entry.error)void managementEntry.load();}if(!managementPage())platformDirectory.clear();if(managementPage()){header();renderPlatformManagement();return;}const landing=prepareNoticeLanding();if(nativePlayerView.open&&!nativePlayerProvisionContext().active){const form=nativePlayerView.form;closeNativePlayerProvision();if(form&&$('#native-player-form')===form)$('#dialog')?.close();}if(playerArchiveView.open&&(!isSuperAdmin()||playerArchiveIdentity()!==playerArchiveView.identity)){playerArchiveView.open=false;$('#dialog')?.close();}applyHomeTheme();header();if(!isAdmin()&&unavailableReadScope===syncReadIdentity()){$('#app').innerHTML='<section class="card"><h2>歌本整理中 ♡</h2><p>管理員完成資料移轉後就能開始點歌。</p>'+button('主播後台','admin')+'</section>';return;}if(route==='admin'&&admin)renderAdmin();else if(route==='common-book')renderCommonBook();else if(route==='book')renderBook();else if(route==='center'&&session)renderCenter();else if(route==='gallery')renderGallery();else renderHome();syncThemeDecor();if(route==='admin'&&admin&&tab==='players'&&!selectedPlayer)loadPlayerManagement();loadVisibleFavoriteFlags();loadFavoriteAudience();loadFavorites();loadListeningOverview();achievementPanel.load().catch(()=>{});medalManagement.load().catch(()=>{});activityPage.load().catch(()=>{});if($('#app')?.dataset)rememberView(document,pageViewKey());renderNoticeLanding(landing);syncPhotoCarousel();updateAppStart(state.currentStreamer,roomContextHref(),{enabled:!demo,prepareSource:source=>appInstall.prepareSource(source)});}

function noticeLandingIdentity(){return JSON.stringify([admin?.accountId,admin?.sessionId||admin?.token,admin?.role,admin?.streamerSlug,session?.accountId,session?.sessionId||session?.token,session?.playerId,state.currentStreamer?.spaceId,state.currentStreamer?.id]);}
function prepareNoticeLanding(){
 const target=pendingNoticeTarget;if(!target||entryPending||!state.currentStreamer||target.section==='admin'&&!admin||target.section==='center'&&!session)return null;
 pendingNoticeTarget=null;noticeLanding=null;
 if(!noticeTargetMatchesRoom(target,{spaceId:state.currentStreamer.spaceId||'space-001',roomId:state.currentStreamer.id,streamerSlug})){toast('這則通知的主播或空間與目前頁面不同，請從原通知重新開啟。');return null;}
 const management=target.section==='admin',kind=notificationTargetView(target),plan=planNotificationLanding(target,{kind,queue:state.queue,ledger:state.ledger,wishes:state.wishes,playerId:session?.playerId,management,roomId:state.currentStreamer.id,currentPool:venuePolicySettings(state.settings).current_space,ledgerPool:venuePolicyLedgerPool,timeValue,historyOrder:listSorts.queueHistory,currentOrder:listSorts.queueCurrent});
 route=management?'admin':'center';if(management){selectedPlayer=null;tab=kind==='credit'?'ledger':kind==='queue'?'queue':kind==='wish'?'wishes':tab;if(kind==='queue')queueHistory=plan.history;if(kind==='credit')ledgerQuery='';}else subtab=target.entityType==='achievement'?'achievements':kind==='credit'?'ledger':kind==='queue'?'queue':kind==='wish'?'wishes':'overview';
 if(plan.pageKey)pages[plan.pageKey]=plan.page;
 const current=new URL(location.href);current.hash=route;history.replaceState(null,'',current.href);
 noticeLanding={...plan,target,route,tab:management?tab:subtab,account:noticeLandingIdentity()};return noticeLanding;
}
function renderNoticeLanding(landing){
 const waiting=pendingNoticeTarget&&(!admin&&pendingNoticeTarget.section==='admin'||!session&&pendingNoticeTarget.section==='center');
 if(waiting){$('#app').insertAdjacentHTML('afterbegin','<div class="notice notice-target-banner">請先登入，查看這則通知的紀錄。 '+button('登入查看','noticeTargetLogin','','tiny')+'</div>');return;}
 const current=noticeLanding;if(!current||current.route!==route||current.tab!==(route==='admin'?tab:subtab)||current.account!==noticeLandingIdentity()||current.found&&!current.detail&&current.pageKey&&pages[current.pageKey]!==current.page)return;
 const text=current.found?'已定位到這則通知的'+(current.kind==='credit'?'存歌紀錄':current.kind==='wish'?'許願紀錄':'點歌紀錄')+'。':current.kind==='queue'||current.kind==='credit'?'這筆紀錄已移除或目前無法查看，已開啟對應列表。':current.kind==='chat'?'已開啟私訊；較早的訊息請在對話中查看。':current.kind==='board'?'已開啟留言板；原留言或回覆請在列表中查看。':'已開啟通知對應的頁面。';
 $('#app').insertAdjacentHTML('afterbegin','<div class="notice notice-target-banner" role="status">'+h(text)+' '+button('收起','noticeTargetDismiss','','tiny')+'</div>');
 const selector=current.kind==='credit'?'[data-ledger-id]':current.kind==='wish'?'[data-wish-id]':'[data-queue-id]',row=[...document.querySelectorAll(selector)].find(el=>(el.dataset.ledgerId||el.dataset.queueId||el.dataset.wishId)===current.id);if(row){row.classList.add('notification-target');row.tabIndex=-1;}
 if(!landing)return;
 requestAnimationFrame(()=>{if(noticeLanding!==current||current.account!==noticeLandingIdentity()||current.route!==route||current.tab!==(route==='admin'?tab:subtab)||$('#dialog').open)return;if(current.detail){const record=current.row;modal('通知中的存歌紀錄','<p>'+h(playerName(record.playerId))+'</p><b>'+h(record.amount)+' 首 · '+h(venueName(venuePolicyLedgerPool(record)))+'</b><p>'+h(time(record.at))+'</p><p>'+h(record.note)+'</p>'+button('知道了','close'));}else if(row){row.scrollIntoView({block:'center',behavior:'auto'});row.focus({preventScroll:true});}else if(current.kind==='chat'||current.kind==='board')openCommunicationNotice(current).catch(e=>toast(e.message));});
}
async function openCommunicationNotice(landing){
 const valid=()=>noticeLanding===landing&&landing.account===noticeLandingIdentity()&&landing.route===route&&landing.tab===(route==='admin'?tab:subtab)&&!document.querySelector('dialog[open]');
 if(!valid())return;
 const controller=landing.kind==='chat'?chat:board;
 if(!landing.target.notificationId){await controller.open();return;}
 let target;
 try{target=await api({op:'noticeTarget',notificationId:landing.target.notificationId,management:landing.target.section==='admin'});}
 catch(error){if(!valid()||error.staleResponse)return;toast('原內容目前無法查看，已開啟對應列表。');await controller.open();return;}
 if(!valid())return;
 if(target.found===true){await controller.open(target);return;}
 toast('原內容目前無法查看，已開啟對應列表。');await controller.open();
}
async function navigateNotice(notice){
 if($('#dialog').open)throw Error('請先關閉目前的編輯視窗，再查看通知。');
 const room=state.streamers?.find(row=>row.id===notice.streamer_id);if(!room)throw Error('目前無法查看這則通知的主播，請重新開啟通知。');
 const target=validateNotificationTarget({...canonicalNoticeLink(notice,room.slug),spaceId:notice.space_id||room.spaceId||admin?.spaceId||session?.spaceId||'space-001'});if(!target)throw Error('這則通知沒有可開啟的目標。');
 if(target.streamerSlug!==streamerSlug||target.spaceId!==(state.currentStreamer?.spaceId||'space-001')){const destination=new URL(notificationTargetPath(target),spaceMount);if(demo)destination.searchParams.set('demo','1');location.href=destination.href;return;}
 const current=new URL(location.href),params=new URL(notificationTargetPath(target),spaceMount).searchParams;for(const key of ['streamer','streamerId','spaceId','entityType','entityId','notificationId'])current.searchParams.delete(key);for(const [key,value]of params)current.searchParams.set(key,value);current.hash=target.section;history.replaceState(null,'',current.href);pendingNoticeTarget=target;render();
}

