async function requestSong(id,kind,selfProvided=false){if(!session)return loginDialog();const item=song(id);if(!item)return toast('歌曲已更新');const c=crownFor(state,id,clock()),other=c&&c.playerId!==session.playerId;if(other)kind='live';const cost=Number(item.creditCost??1);let insufficient=false;if(kind==='saved')try{venuePolicySavedSnapshot(state,session.playerId,cost);}catch{insufficient=true;}if(insufficient){modal('沒有可提的存歌','<p>目前沒有足夠的存歌可提這首歌。</p><div class="actions">'+button('前往現點','request',id,'primary','data-kind="live"')+'</div>');return;}const expectedSong=songSelection(item),pairSelections=new Map([item.songId,...(item.pairSongIds||[])].map(id=>song(id)).filter(Boolean).map(row=>[row.songId,songSelection(row)]));const visibleRevision=state.revision;const liveHelp=button('點歌教學','prices','','tiny');modal(kind==='saved'?'🎤 確認提歌':'🎁 確認現點','<h3>'+h(item.title)+'－'+h(item.artist)+'</h3>'+shortSongOptions(item)+'<div id="request-cost-summary"></div>'+(kind==='live'?check('gift','我已確認禮物價格')+liveHelp:'')+field('requestNote','想說的話（選填，最多 30 字）','','text','maxlength="60" autocomplete="off"'),async f=>{if(state.revision!==visibleRevision)throw Error('歌曲或價格已更新，請重新開啟確認視窗');const data={songId:id,expectedSong,...(f.get('pairSongId')?{expectedPair:pairSelections.get(f.get('pairSongId'))}:{}),kind,selfProvided,source:selfProvided?'draw':'manual',pairSongId:f.get('pairSongId')||'',giftConfirmed:f.has('gift'),requestNote:f.get('requestNote')||''};try{await dispatch('request',data);toast(say('success'));}catch(e){if(kind==='saved'){if((e.message.includes('本小時真的滿')||e.message.includes('提歌額度不足'))&&!demo)try{await api({op:'failedRequest',songId:id,expectedSong,...(data.expectedPair?{expectedPair:data.expectedPair}:{}),pairSongId:data.pairSongId});}catch{}if((e.message.includes('本小時真的滿')||e.message.includes('提歌額度不足'))||e.message.includes('存歌袋空空')||e.message.includes('可用存歌不足'))e.liveSongId=id;}throw e;}});const refreshCost=()=>{const pairSongId=$('#modal-form [name=pairSongId]')?.value||'',q=quoteSong(state,id,{pairSongId},session.playerId,clock()),fees=requestFees(state,c,session.playerId,q.creditCost);$('#request-cost-summary').textContent=kind==='saved'?'此歌曲占 '+q.creditCost+' 首存歌及本小時提歌額度，完成演唱才扣存歌。':'現點 '+money(fees.price)+' 探鑽＋雙費 '+money(fees.double)+' 探鑽（'+q.creditCost+' 首，不占提歌名額）';};refreshCost();$('#modal-form').addEventListener('change',refreshCost);}

