async function compress(file,max=1400){if(!file||!file.type.startsWith('image/'))throw new Error('請選圖片');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/webp',.82).split(',')[1];}
function editCard(id){const c=state.cards.find(c=>c.id===id)||{},fields=cardDisplay(c);modal('🖼️ 卡片管理',`${field('file','上傳照片／影片（影片最多 20 MB）','','file','accept="image/*,video/mp4,video/webm"')}${select('playerId','綁定玩家（選填）',[['','不綁定'],...playerOptions(c.playerId).slice(1)],c.playerId)}${area('description','簡述',c.description||'')}${field('startsAt','開始時間',dateInput(c.startsAt||clock()),'datetime-local','required')}${field('expiresAt','到期時間（留空永久）',dateInput(c.expiresAt),'datetime-local')}<fieldset><legend>前台顯示欄位</legend>${Object.entries(CARD_FIELDS).map(([key,label])=>check('show.'+key,label,fields[key])).join('')}</fieldset>`,async f=>{let url=c.url,thumbnail=c.thumbnail,mediaType=c.mediaType||'image';const file=f.get('file');if(file?.size){if(demo)throw Error('卡片上傳需連接正式後台');if(['video/mp4','video/webm'].includes(file.type)){if(file.size>20*1024*1024)throw Error('影片最多 20 MB');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('影片讀取失敗'));reader.readAsDataURL(file);});url=(await api({op:'uploadVideo',video:encoded,mime:file.type})).url;thumbnail=url;mediaType='video';}else{url=(await api({op:'upload',image:await compress(file),mime:'image/webp'})).url;thumbnail=(await api({op:'upload',image:await compress(file,480),mime:'image/webp'})).url;mediaType='image';}}await dispatch('card',{id:c.id,url,thumbnail,mediaType,displayFields:Object.fromEntries(Object.keys(CARD_FIELDS).map(k=>[k,f.has('show.'+k)])),playerId:f.get('playerId'),description:f.get('description'),startsAt:isoInput(f.get('startsAt')),expiresAt:isoInput(f.get('expiresAt'))});});}
