function editVenue(){const settings=venuePolicySettings(state.settings);modal('📻 電台設定',check('radio_enabled','啟用電台',settings.radio_enabled)+nativeSelect('current_space','目前場域',[['shengma','聲瑪'],['radio','📻 電台']],settings.current_space)+'<p class="muted">啟用後可在待播頁切換場域。電台與聲瑪共用歌本及每小時提歌額度，存歌池分開；既有待播與演唱保留原場域。</p>',async f=>dispatch('settings',{radio_enabled:f.has('radio_enabled'),current_space:f.has('radio_enabled')?f.get('current_space'):'shengma'}));const enabled=$('#dialog [name=radio_enabled]'),current=$('#dialog [name=current_space]');const update=()=>{current.disabled=!enabled.checked;};enabled.addEventListener('change',update);update();}
