async function updateSearch(input){const id=input.id;try{
 if(input.matches('[data-entity-query]')){const box=input.closest('.entity-picker');box.querySelector('[type=hidden]').value='';showEntityResults(box);}
 if(id==='login-query'){const seq=++querySequence,q=input.value,rows=demo?playerSearch(full,q,true).slice(0,20):(await api({op:'search',query:q})).players;if(seq!==querySequence||!$('#login-results'))return;$('#login-results').innerHTML=q?rows.map(p=>`<div class="song"><div class="info"><b>${h(p.name)}</b><small>${h(p.ids.join('、'))}</small></div>${button('登入','chooseLogin',p.playerId)}</div>`).join('')||blank('找不到玩家'):'';}
  if(id==='home-search'){const q=input.value;roomSearch.generation++;clearTimeout(roomSearch.timer);$('#home-results').innerHTML=q?blank('搜尋中…'):blank('給我一點線索，幫你翻歌本 ♡');if(q)roomSearch.timer=setTimeout(()=>loadRoomSongSearch('home',q,[],0),350);}
  if(input.matches('[data-tag-search]')){for(const label of document.querySelectorAll('.search-tags label'))label.hidden=!label.textContent.toLocaleLowerCase().includes(input.value.toLocaleLowerCase());}
 if(id==='song-q'){filters.q=input.value;pages[isAdmin()?'songs':'book']=1;roomSearch.generation++;clearTimeout(roomSearch.timer);renderSongResults();if(filters.q.trim())roomSearch.timer=setTimeout(()=>loadRoomSongSearch(isAdmin()?'songs':'book',filters.q,filters.tags,0),350);}
 if(id==='player-query'){const mode=playerManagement.state().mode;playerInputs[mode]=input.value;if(localPlayerManagement()){adminQuery=input.value;pages['players-'+mode]=1;$('#player-results').innerHTML=playerResults(mode);}}
 if(id==='ledger-query'){ledgerQuery=input.value;pages.ledger=1;const holder=document.createElement('div');holder.innerHTML=ledgerRows(null,true);$('#ledger-results').replaceWith(holder.querySelector('#ledger-results'));}
 if(id==='stats-day'){
  const target=$('#stats-result'),day=input.value,scope=syncReadIdentity();target.innerHTML=blank('讀取帳務摘要…');
  try{const value=demo||draft&&isAdmin()?stats(state,day+'T'+String(accountingRollover(state)).padStart(2,'0')+':00:00+08:00'):(await api({op:'accountingSummary',day,management:true})).summary;
   if(scope===syncReadIdentity()&&input.isConnected&&input.value===day&&$('#stats-result')===target)target.innerHTML=statsHtml(value);
  }catch(error){if(scope===syncReadIdentity()&&input.isConnected&&input.value===day&&$('#stats-result')===target)target.innerHTML=blank('帳務摘要尚未確認：'+error.message);}
 }
}catch(err){toast(err.message);}}
async function start(){const requestedPage=route;if(demo){const catalog=await (await fetch('src/catalog.json')).json();full=get('demo')||migrateLegacy({songs:catalog,users:[],queue:[],crowns:[]});if(full.schemaVersion<3){put('before-v3',full);seedPreviewCrowns(full);full=upgradePlatform(full);}put('demo',full);}if(route==='admin'&&!admin)route='home';const incoming=new URL(location.href),songId=incoming.searchParams.get('commonRequest'),kind=incoming.searchParams.get('commonKind');if(songId&&songId.length<=200&&['saved','live'].includes(kind)){pendingCommonRequest={songId,kind};incoming.searchParams.delete('commonRequest');incoming.searchParams.delete('commonKind');history.replaceState(null,'',incoming.href);}try{
// The portal selects a login form only; membership and permissions stay server-verified.
const portalMode=incoming.searchParams.get('portalLogin');
if(!demo&&['player','admin'].includes(portalMode)){
 incoming.searchParams.delete('portalLogin');history.replaceState(history.state,'',incoming.href);
 route=portalMode==='admin'?'admin':'home';
 if(portalMode==='admin'?!admin:!session){
  // A selected room must load its scoped directory before opening login.
  // The global entry placeholder contains only the seeded papa descriptor.
  if(entryPending)showSpaceEntry();else {route='home';await refresh(true);}
  if(portalMode==='admin')await adminLogin();else await loginDialog();return;
 }
}
if(managementPage()&&(admin||session)){render();return;}if(entryPending&&!await openSpaceEntry())return;await refresh(true);if((admin||session)&&!demo)void managementEntry.load();if(route==='common-book')await loadCommonBook(0);if(typeof publicRouteContext!=='undefined'&&publicRouteContext){if(requestedPage==='admin'&&!admin)await adminLogin();else if(requestedPage==='center'&&!session)await loginDialog();}if(pendingCommonRequest){if(session){const item=pendingCommonRequest;pendingCommonRequest=null;await requestSong(item.songId,item.kind);}else await loginDialog();}}catch(e){header();$('#app').innerHTML=card('連線還沒準備好',`<p>${h(e.message)}</p><p class="muted">管理員完成 V2 部署設定後即可使用。現有正式資料沒有被改動。</p>${button('主播後台','admin')}`,true);}}
let lastHour=hourKey(clock());setInterval(()=>{const nextHour=hourKey(clock());if(!entryPending&&!document.hidden&&nextHour!==lastHour){lastHour=nextHour;refresh(true).catch(()=>{});}if($('#hour'))$('#hour').innerHTML=hour();},1000);
// Existing low-frequency revision recovery remains until every business write
// has a room invalidation. Editing delays DOM replacement, not version checks.
setInterval(()=>{if(entryPending||document.hidden||demo||draft)return;refresh().catch(()=>{});},30000);
let lastForegroundCheck=0;
function resumeLiveState(reason){if(document.hidden||navigator.onLine===false){syncRecovery.resume();return;}if(Date.now()-lastForegroundCheck<1000){syncRecovery.resume();return;}lastForegroundCheck=Date.now();syncRecovery.invalidate(reason);}
document.addEventListener('visibilitychange',()=>{syncPhotoCarousel();resumeLiveState('foreground');});
window.addEventListener('focus',()=>resumeLiveState('foreground'));
window.addEventListener('online',()=>resumeLiveState('online'));
window.addEventListener('offline',()=>syncRecovery.resume());
document.addEventListener('focusout',()=>queueMicrotask(()=>syncRecovery.flushRender()));
document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO'){e.target.dataset.cardPlaying='1';if(homeCardVideo(e.target)){photoCarouselVideos.add(e.target);syncPhotoCarousel();}}},true);
for(const event of ['pause','ended'])document.addEventListener(event,e=>{if(e.target.tagName==='VIDEO'){
 if(event==='ended'||e.target.ended||!photoCarouselVideos.has(e.target)||!homeCardVideo(e.target)){delete e.target.dataset.cardPlaying;photoCarouselVideos.delete(e.target);}
 syncPhotoCarousel();queueMicrotask(()=>syncRecovery.flushRender());
}},true);
for(const event of ['emptied','error'])document.addEventListener(event,e=>{if(homeCardVideo(e.target)||photoCarouselVideos.has(e.target)){delete e.target.dataset.cardPlaying;photoCarouselVideos.delete(e.target);syncPhotoCarousel();queueMicrotask(()=>syncRecovery.flushRender());}},true);
document.addEventListener('close',()=>queueMicrotask(()=>{syncPhotoCarousel();syncRecovery.flushRender();syncRecovery.resume();}),true);
syncPhotoCarousel();
for(const event of ['popstate','hashchange'])window.addEventListener(event,()=>restorePageLocation().catch(e=>toast(e.message)));

function queueRemovalHint(q){if(q.allocation_model==='reservation-v1')return '這首尚未演唱；取消後釋放已保留的 '+(q.creditCost||1)+' 首存歌，不另外新增退款，原始收歌與取消紀錄保留。';return q.allocation_id?'這首尚未演唱；取消後依原預扣分配回補 '+(q.creditCost||1)+' 首存歌，保留回補與取消紀錄。':q.kind==='saved'?'取消會釋放保留的存歌及提歌額度；完成演唱才扣存歌。':'取消後保留點歌紀錄。';}
function completeQueue(id){
 const q=state.queue.find(row=>row.id===id);if(!q||q.status!=='waiting')throw Error('待播已異動，請重新確認');
 modal('完成演唱','<h3>'+h(q.title)+'</h3>'+field('effective_at','實際完成時間',dateInput(q.recordedAt||clock()),'datetime-local','required')+'<div id="queue-carry-choice"></div><p class="muted">完成時依來源結算一次；過檔只調整提歌額度，不重複扣存歌。時間填錯可在歷史中修正。</p>',async f=>{
  const at=isoInput(f.get('effective_at')),crossed=['saved','live'].includes(q.kind)&&queueCrossedHour(q,at);
  if(crossed&&!['yes','no'].includes(f.get('carryOver')))throw Error('請選擇這首是否過檔');
  await dispatch('queue',{id,operation:'complete',effective_at:at,...(crossed?{carryOver:f.get('carryOver')==='yes'}:{})});
 });
 const input=$('#dialog [name=effective_at]'),choice=$('#queue-carry-choice');let shown=false;
 const update=()=>{const crossed=['saved','live'].includes(q.kind)&&Number.isFinite(timeValue(input.value))&&queueCrossedHour(q,input.value);if(crossed===shown)return;shown=crossed;choice.innerHTML=crossed?'<fieldset class="queue-carry-options"><legend>這首跨小時了，要過檔嗎？</legend><label class="check-row"><input type="radio" name="carryOver" value="no" required>否，保留原小時額度</label><label class="check-row"><input type="radio" name="carryOver" value="yes" required>是，計入實際完成的小時</label></fieldset>':'';};
 input.addEventListener('input',update);update();
}
async function queueLyrics(id){
 const q=state.queue.find(q=>q.id===id);if(!q)return toast('紀錄已更新');
 const items=q.items?.length?q.items:[{songId:q.songId,title:q.title,artist:q.artist}];
 const part=(item,body,note='')=>'<h3>'+h(item.title||song(item.songId)?.title||q.title)+'</h3><small>'+h(item.artist||song(item.songId)?.artist||'')+'</small><div class="notice catalog-lyric-body">'+h(body||'這首尚未填入歌詞，可到歌曲管理補充。')+'</div>'+(note?'<small>演唱註記：'+h(note)+'</small>':'');
 if(demo||draft){modal('查看歌詞',items.map(item=>part(item,song(item.songId)?.lyrics)).join(''));return;}
 modal('查看歌詞','<div id="queue-lyrics-content">讀取歌詞中…</div>');
 const holder=$('#queue-lyrics-content'),pending=new Map();
 const result=await Promise.all(items.map(async item=>{try{if(!pending.has(item.songId))pending.set(item.songId,api({op:'catalogLyrics',streamerSongId:item.songId,management:true}));const row=await pending.get(item.songId);return part(item,row.body??row.lyrics??song(item.songId)?.lyrics,row.privateNote);}catch(err){return part(item,'歌詞暫時無法載入：'+err.message);}}));
 if(holder&&holder===$('#queue-lyrics-content'))holder.innerHTML=result.join('');
}
