 const originalPair=q.items?.length>1?q.items[1].songId:(q.items?.[0]?.performances===2?q.songId:''),originalTime=dateInput(q.at),choices=state.songs.map(s=>[s.songId,s.title+'－'+s.artist]);
 if(!choices.some(([id])=>id===q.songId))choices.push([q.songId,q.title+'－'+q.artist]);
