function select(name,label,values,value){if(!['playerId','songId'].includes(name))return nativeSelect(name,label,values,value);const match=values.find(v=>String(v[0])===String(value)),optional=label.includes('選填');return `<div class="entity-picker" data-entity-kind="${name}"><label>${h(label)}<input type="search" data-entity-query autocomplete="off" placeholder="${name==='playerId'?'搜尋玩家名稱、ID、曾用名':'搜尋歌名、歌手、語言、標籤'}" value="${h(match?.[0]?match[1]:'')}" aria-label="${h(label)}搜尋" ${optional?'':'required'}></label><input type="hidden" name="${name}" value="${h(value||'')}"><div class="entity-results"></div></div>`;}
function showEntityResults(box){const input=box.querySelector('[data-entity-query]'),q=input.value.trim(),kind=box.dataset.entityKind,rows=q?(kind==='playerId'?playerSearch(state,q):state.songs.filter(s=>matchesSong(s,q))):[];box.querySelector('.entity-results').innerHTML=q?(rows.slice(0,12).map(r=>button(h(kind==='playerId'?r.name+' · '+(r.ids.join('、')||'無平台 ID'):r.title+'－'+r.artist),'pickEntity',kind==='playerId'?r.playerId:r.songId,'entity-option')).join('')||'<small>沒有符合的資料</small>')+(rows.length>12?'<small>再輸入幾個字，縮小搜尋範圍 ♡</small>':''):'';}

document.addEventListener('submit',e=>{for(const box of e.target.querySelectorAll('.entity-picker')){const input=box.querySelector('[data-entity-query]');if((input.required||input.value.trim())&&!box.querySelector('[type=hidden]').value){e.preventDefault();e.stopImmediatePropagation();$('#dialog-error').textContent='請從搜尋結果點選正確的玩家或歌曲';input.focus();return;}}},true);
function seedPreviewCrowns(s){if(s.previewCrownsRestored)return;s.previewCrownsRestored=true;for(const [id,title,artist] of [['legacy-crown-1','三心愛意','不不玩家'],['legacy-crown-2','crazy 1 night','葵葵']]){if(!s.crowns.some(c=>c.id===id||c.title===title))s.crowns.push({id,title,artist,ownerName:'不不玩家',playerId:null,songId:null,tier:'至尊卡',fee:925000,price:55599,double:18188,months:0,activatedAt:null,expiresAt:null,legacyDisplay:true,note:'原網站冠歌：永久；生效時間未知。請核對綁定與款項，不自動設定生效時間。'});}}

function playerResults(mode='stored'){let rows=playerSearch(state,adminQuery);if(mode==='stored')rows=rows.filter(p=>balance(state,p.playerId)>0);const page=paginate(rows,'players-'+mode);return playerRowsHtml(page.rows)+page.nav;}

function adminSongPage(){return bookSearchResult()||paginate(filteredSongs(),'songs',20);}
function adminSongList(){const p=adminSongPage();return sortControl('songs')+(p.loading?blank('搜尋中…'):adminSongResults(p.rows)+(p.nav||''));}
const favoriteAudienceCache=new Map();let favoriteAudiencePending=null,favoriteAudienceDialog=null,favoriteAudienceGeneration=0;
function favoriteAudienceKey(){return [admin?.accountId,admin?.token,admin?.sessionId,state.currentStreamer?.spaceId,state.currentStreamer?.id].join('|');}
async function loadFavoriteAudience(){
 if(!isAdmin()||demo||draft||route!=='admin'||tab!=='songs')return;
 const buttons=[...document.querySelectorAll('[data-favorite-audience]')],ids=buttons.map(b=>b.dataset.favoriteAudience);if(!ids.length||ids.length>50)return;
 const key=favoriteAudienceKey(),cacheKey=key+'|'+ids.join('|'),cached=favoriteAudienceCache.get(cacheKey);
 const paint=counts=>{if(key!==favoriteAudienceKey())return;for(const b of document.querySelectorAll('[data-favorite-audience]')){const n=counts[b.dataset.favoriteAudience];if(Number.isSafeInteger(n)&&n>=0){b.textContent='❤️ '+n+'人';b.disabled=false;b.removeAttribute('title');}}};
 if(cached&&Date.now()-cached.at<60000){paint(cached.counts);return;}if(favoriteAudiencePending?.key===cacheKey)return favoriteAudiencePending.promise;
 const promise=api({op:'favoriteAudience',songIds:ids,management:true}).then(result=>{if(key!==favoriteAudienceKey())return;const counts=result?.counts;if(!counts||ids.some(id=>!Number.isSafeInteger(counts[id])||counts[id]<0))throw Error('收藏人數尚未確認');favoriteAudienceCache.set(cacheKey,{counts,at:Date.now()});if(favoriteAudienceCache.size>20)favoriteAudienceCache.delete(favoriteAudienceCache.keys().next().value);paint(counts);}).catch(()=>{if(key===favoriteAudienceKey())for(const b of buttons){b.title='尚未讀取，點擊重試';b.disabled=false;b.textContent='❤️ —人';}}).finally(()=>{if(favoriteAudiencePending?.key===cacheKey)favoriteAudiencePending=null;});
 favoriteAudiencePending={key:cacheKey,promise};return promise;
}
async function openFavoriteAudience(songId,page=0){
 if(!isAdmin()||demo||draft)return;const key=favoriteAudienceKey(),generation=++favoriteAudienceGeneration;
 favoriteAudienceDialog={songId,page,key};modal('收藏玩家',blank('讀取中…'));
 try{const result=await api({op:'favoriteAudience',songIds:[songId],songId,page,management:true});if(generation!==favoriteAudienceGeneration||key!==favoriteAudienceKey()||!$('#dialog').open)return;
 if(result?.songId!==songId||result.page!==page||!Number.isSafeInteger(result.total)||result.total<0||!Array.isArray(result.rows)||result.rows.length>20||result.rows.some(r=>typeof r.name!=='string'))throw Error('收藏名單尚未確認');
 for(const b of document.querySelectorAll('[data-favorite-audience]'))if(b.dataset.favoriteAudience===songId)b.textContent='❤️ '+result.total+'人';for(const entry of favoriteAudienceCache.values())if(Object.hasOwn(entry.counts,songId))entry.counts[songId]=result.total;
 const max=Math.max(1,Math.ceil(result.total/20));if(page>=max)return openFavoriteAudience(songId,max-1);
 modal('收藏玩家',result.rows.map(r=>'<p>'+h(r.name)+'</p>').join('')+(result.total?'':blank('目前沒有玩家收藏'))+'<div class="pagination">'+button('上一頁','favoriteAudiencePage',page-1,'',page===0?'disabled':'')+'<span>共 '+result.total+' 人 · 共 '+max+' 頁</span><input id="favorite-audience-page" type="number" min="1" max="'+max+'" value="'+(page+1)+'" aria-label="收藏名單頁碼">'+button('跳頁','favoriteAudienceJump')+button('下一頁','favoriteAudiencePage',page+1,'',page+1>=max?'disabled':'')+'</div>');
 }catch(error){if(generation===favoriteAudienceGeneration&&key===favoriteAudienceKey()&&$('#dialog').open)modal('收藏玩家','<p class="error">'+h(error.message)+'</p>');}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-favorite-audience]');if(b)openFavoriteAudience(b.dataset.favoriteAudience);});
document.addEventListener('keydown',e=>{if(e.target.id==='favorite-audience-page'&&e.key==='Enter'&&!e.isComposing){e.preventDefault();if(favoriteAudienceDialog)openFavoriteAudience(favoriteAudienceDialog.songId,Math.max(0,Math.min(Number(e.target.max)-1,Math.floor(Number(e.target.value)||1)-1)));}});
function adminSongResults(rows=adminSongPage().rows){return rows.map(s=>{const status=s.catalogStatus||'unlinked';return `<div class="song selectable-song ${selectedSongs.has(s.songId)?'is-selected':''}"><label class="song-check"><input type="checkbox" data-song-select="${h(s.songId)}" aria-label="選取 ${h(s.title)}" ${selectedSongs.has(s.songId)?'checked':''}></label><div class="info"><b>${h(s.title)}${s.new?' <span class="tag">✨ 新練</span>':''}${s.hidden?' <span class="tag" title="隱藏歌曲" aria-label="隱藏歌曲"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M3 3l18 18M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/></svg></span>':''}</b><small>${h(s.artist)} · ${h(s.cat)} · ${plays(s)} 次</small><small>${h(({linked:'已綁定',pending:'待審核',unlinked:'未綁定'})[status])}${status==='linked'?' · '+h(s.version||'原版'):''}</small><div class="song-tags">${s.tags?.length?s.tags.map(t=>`<span class="tag">${h(t)}</span>`).join(''):'<small class="subtle">尚未貼標籤</small>'}</div>${s.murmur?`<div class="subtle">💬 ${h(s.murmur)}</div>`:''}</div><div class="actions song-primary-actions"><button type="button" class="tiny" data-favorite-audience="${h(s.songId)}" disabled aria-label="查看收藏玩家">❤️ —人</button>${s.hidden?button('恢復顯示','songHide',s.songId,'tiny'):''}${button('編輯','editSong',s.songId)}<details class="song-more"><summary>更多</summary><div class="actions">${button('刪除','deleteSong',s.songId,'tiny danger')}${status==='linked'?(Number(s.otherStreamerCount)>0?button('誰也會唱','songOtherSingers',s.songId):''):button('前往共同曲庫','songLink',s.songId)}${button(s.hidden?'解除隱藏':'隱藏','songHide',s.songId)}${button('💬 碎碎念','editMurmur',s.songId)}${button('歌詞／註記','streamerLyrics',s.songId)}</div></details></div></div>`;}).join('')||blank('沒有符合的歌曲');}
function songBatchBar(){for(const id of selectedSongs)if(!song(id))selectedSongs.delete(id);const found=bookSearchResult(),matches=found?found.rows:filteredSongs(),visible=found?found.rows:adminSongPage().rows,all=visible.length&&visible.every(s=>selectedSongs.has(s.songId));return `<details class="song-batch-tools" ${selectedSongs.size?'open':''}><summary>批次操作${selectedSongs.size?' · 已選 '+selectedSongs.size+' 首':''}</summary><div class="batch-toolbar"><label class="check-row"><input type="checkbox" data-select-song-page ${all?'checked':''} ${visible.length?'':'disabled'}>本頁全選</label><strong role="status" aria-live="polite">已選 ${selectedSongs.size} 首</strong>${button((found?'選取本頁搜尋結果（':'選取搜尋結果（')+matches.length+'）','selectFilteredSongs','', 'tiny', matches.length?'':'disabled')}${button('取消選取','clearSongSelection','','tiny',selectedSongs.size?'':'disabled')}${button('批次編輯／貼標籤','bulkEditSongs','','tiny primary',selectedSongs.size?'':'disabled')}${button('刪除已選','deleteSelectedSongs','','tiny danger',selectedSongs.size?'':'disabled')}${songUndo&&songUndo.until>Date.now()?button('復原剛才的批次修改','undoSongBatch'):''}</div><small>可跨頁選取；搜尋不會清除已選歌曲。</small></details>`;}
function renderSongResults(){queueMicrotask(loadFavoriteAudience);if(!$('#song-list'))return;const p=isAdmin()?adminSongPage():bookSearchResult()||paginate(filteredSongs(),'book',20);$('#song-list').innerHTML=sortControl(isAdmin()?'songs':'book')+(p.loading?blank('搜尋中…'):(isAdmin()?adminSongResults(p.rows):songRows(p.rows))+(p.nav||''));if($('#song-batch-bar')){$('#song-batch-bar').innerHTML=songBatchBar();const rows=p.rows,checked=rows.filter(s=>selectedSongs.has(s.songId)).length,all=$('[data-select-song-page]');if(all)all.indeterminate=checked>0&&checked<rows.length;}}
document.addEventListener('change',e=>{if(e.target.id==='song-catalog-status'){songCatalogStatusFilter=e.target.value;pages.songs=1;roomSearch.generation++;clearTimeout(roomSearch.timer);renderSongResults();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-song-select]')){const id=e.target.dataset.songSelect;e.target.checked?selectedSongs.add(id):selectedSongs.delete(id);renderSongResults();}if(e.target.matches('[data-select-song-page]')){for(const s of adminSongPage().rows)e.target.checked?selectedSongs.add(s.songId):selectedSongs.delete(s.songId);renderSongResults();}});
const songEditFields=s=>({cat:s.cat,artistType:s.artistType,tags:s.tags||[],new:!!s.new,murmur:s.murmur||'',creditCost:s.creditCost??1,...(Object.hasOwn(s,'newPracticeAt')?{newPracticeAt:newPracticeDate(s)}:{})});
async function deleteSelectedSongs(){
 const ids=[...selectedSongs].filter(id=>song(id));if(!ids.length)return;
 if(!confirm('刪除已選 '+ids.length+' 首歌曲？既有演唱與點歌歷史保留。有待播、有效冠歌或半首搭配依賴時，整批不會刪除。'))return;
 await dispatch('songsBulk',{songIds:ids,remove:true});selectedSongs.clear();songUndo=null;renderSongResults();toast('已刪除 '+ids.length+' 首歌曲');
}
async function bulkEditSongs(){const ids=[...selectedSongs].filter(id=>song(id));if(!ids.length)return toast('先勾選要修改的歌曲');const languages=await catalogTemplateChoices('languages','',['華語','韓語','台語','其他']),types=await catalogTemplateChoices('performerTypes','',['女歌手','男歌手','團體','合唱','其他']);modal('批次編輯 '+ids.length+' 首歌曲',`<details class="notice"><summary>查看這次選取的 ${ids.length} 首</summary><div class="batch-selection">${ids.map(id=>h(song(id).title)+'－'+h(song(id).artist)).join('<br>')}</div></details><p class="muted">只改你指定的欄位，其餘資料保留。</p><div class="form-grid">${nativeSelect('tagMode','標籤處理',[['keep','不變'],['add','加上勾選標籤'],['remove','移除勾選標籤'],['replace','改成以下標籤'],['clear','清空標籤']],'keep')}${nativeSelect('cat','語言',[['','不變'],...languages],'')}<div class="full chips batch-tag-options">${songTagVocabulary().map(t=>check('tags',t).replace('name="tags"',`name="tags" value="${h(t)}"`)).join('')}</div>${field('customTags','其他標籤（逗號分開）')}${nativeSelect('artistType','歌手分類',[['','不變'],...types],'')}${nativeSelect('new','新練歌曲',[['','不變'],['true','設為新練'],['false','取消新練']],'')}${nativeSelect('murmurMode','碎碎念',[['keep','不變'],['set','統一填寫'],['clear','清空']],'keep')}${field('creditCost','統一扣歌首數（空白不變）','','number','min="0.5" step="0.5"')}${field('murmur','統一的碎碎念','','text','maxlength="40"')}</div><div id="batch-preview" class="notice" aria-live="polite">尚未指定修改項目</div>`,async f=>{const data=bulkSongData(f,ids),before=ids.map(id=>({songId:id,...songEditFields(song(id))}));await dispatch('songsBulk',data);songUndo={before,after:ids.map(id=>({songId:id,...songEditFields(song(id))})),until:Date.now()+10000};clearTimeout(songUndoTimer);songUndoTimer=setTimeout(()=>{songUndo=null;if($('#song-batch-bar'))$('#song-batch-bar').innerHTML=songBatchBar();},10000);renderSongResults();toast('已更新 '+ids.length+' 首歌曲，可在 10 秒內復原');});const form=$('#modal-form');form.addEventListener('change',e=>updateBulkPreview(form,ids,e.target));form.addEventListener('input',e=>{if(!e.isComposing)updateBulkPreview(form,ids,e.target);});}
function bulkSongData(f,ids){const data={songIds:ids,tagMode:f.get('tagMode'),tags:[...f.getAll('tags'),...list(f.get('customTags'))]};for(const k of ['cat','artistType'])if(f.get(k))data[k]=f.get(k);if(f.get('creditCost'))data.creditCost=Number(f.get('creditCost'));if(f.get('new'))data.new=f.get('new')==='true';if('new'in data&&!data.tags.length){if(['add','remove'].includes(data.tagMode))data.tagMode='keep';else if(data.tagMode==='replace')data.tagMode='clear';}if(f.get('murmurMode')!=='keep')data.murmur=f.get('murmurMode')==='clear'?'':f.get('murmur');return data;}
function updateBulkPreview(form,ids,target){let f=new FormData(form);if((f.getAll('tags').length||f.get('customTags').trim())&&f.get('tagMode')==='keep'){form.elements.tagMode.value='add';f.set('tagMode','add');}syncBulkPracticeForm(form,target);f=new FormData(form);const d=bulkSongData(f,ids),parts=[];if(d.tagMode!=='keep')parts.push(({add:'加上標籤：',remove:'移除標籤：',replace:'改成標籤：',clear:'清空一般標籤'})[d.tagMode]+(d.tagMode==='clear'?'':d.tags.join('、')));if(d.creditCost)parts.push('扣歌首數：'+d.creditCost);if(d.cat)parts.push('語言：'+d.cat);if(d.artistType)parts.push('歌手分類：'+d.artistType);if('new'in d)parts.push(d.new?'設為新練歌曲':'取消新練');if('murmur'in d)parts.push(d.murmur?'碎碎念：'+d.murmur:'清空碎碎念');$('#batch-preview').textContent=parts.length?'將修改 '+ids.length+' 首：'+parts.join('；'):'尚未指定修改項目';}
async function undoSongBatch(){if(!songUndo||songUndo.until<Date.now())return toast('復原時間已過');const undo=songUndo;await dispatch('restoreSongEdits',{before:undo.before,after:undo.after});songUndo=null;clearTimeout(songUndoTimer);renderSongResults();toast('已復原剛才的批次修改');}

function editStreamer(id){const r=state.streamers.find(r=>r.id===id)||{};modal(id?'編輯主播':'新增主播',field('display_name','主播名稱',r.display_name||'','text','required')+field('slug','網址名稱（英文）',r.slug||'','text','required')+field('home_title','首頁名稱',r.home_title||'')+field('subtitle','副標題',r.subtitle||'')+field('avatar_url','頭像網址',r.avatar_url||'')+field('banner_url','橫幅網址',r.banner_url||'')+area('description','介紹',r.description||'')+check('active','開放主播頁',r.active!==false)+(id&&isSuperAdmin()?'<div class="actions">'+button('停用主播入口','archiveStreamer',id,'tiny danger')+'</div>':''),async f=>dispatch('streamer',{...formData(f),id:r.id,active:f.has('active')}));}
