function chooseDifferentVersion(id){
 const source=catalogView.items.find(row=>String(row.id)===id);if(!source)return;
 const picked=[...(catalogView.selectedRows?.values()||[])].filter(row=>catalogGroupKey(row)===catalogGroupKey(source));const rows=picked.length?picked:catalogView.items.filter(row=>catalogGroupKey(row)===catalogGroupKey(source));
 modal('選擇這次要建立的版本', '<p>不同演唱者或版本分開處理。先選一筆來源，再選共同作品並建立版本；其餘來源保留待審。</p><p class="muted">若還沒有共同作品，先核准其中一筆，再將其他版本歸到該作品。</p>'+rows.map(row=>'<div class="song"><div class="info"><b>'+h(row.title)+'－'+h(row.artist)+'</b><small>'+h([state.streamers.find(room=>room.id===row.streamerId)?.display_name||row.streamerId,row.language,row.versionLabel].filter(Boolean).join(' · '))+'</small></div>'+button('選擇此版本來源','catalogVersionSource',row.id)+'</div>').join(''));
}
function catalogReviewHtml(){
 const sections=isSuperAdmin()?[['singles','單筆待審'],['duplicates','疑似重複'],['confirmed','已確認歌曲'],['approved','版本關係'],['issues','問題回報'],['templates','設定'],['history','變更紀錄']]:[['approved','版本關係'],['issues','我的問題回報']];
 const status=catalogView.section,counts=catalogView.counts||{},tabs='<div class="tabs">'+sections.map(([key,label])=>button(label+(counts[key]!=null?'（'+counts[key]+'）':''),'catalogSection',key,status===key?'active':'')).join('')+'</div>';
 if(status==='templates')return tabs+catalogTemplateHtml();
 if(status==='confirmed')return tabs+button('查看／管理已確認歌曲','catalogConfirmed','','primary');
 const room=id=>state.streamers.find(r=>r.id===id)?.display_name||id||'';
 const rowHtml=row=>'<div class="song catalog-row"><label class="catalog-check"><input type="checkbox" data-catalog-review="'+h(row.id)+'" '+(catalogView.selected.has(row.id)?'checked':'')+' aria-label="選取 '+h(row.title)+'"></label><div class="info"><b>'+h(row.title)+'｜'+h(row.artist)+'</b><small>'+h([room(row.streamerId),row.language,row.performerType,row.versionLabel].filter(Boolean).join(' · '))+'</small>'+(row.preferredFamily?'<small>主播指定：同一首，但不同版本</small>':'')+'</div>'+button('編輯','catalogCandidateEdit',row.id,'tiny')+button(row.preferredFamily?'指定共同作品／版本':'關聯既有共同歌曲／版本','catalogVersionSource',row.id,'tiny')+'</div>';
 let entries='',actions='';
 if(status==='singles'){
  entries=catalogView.items.map(row=>'<section class="catalog-single-candidate">'+rowHtml(row)+'</section>').join('');
  actions=button('批次通過單筆待審','catalogReviewAction','approve_new','',catalogView.selected.size?'':'disabled')+button('人工指定同一首','catalogReviewSame','','',catalogView.selected.size>=2?'':'disabled');
 }else if(status==='duplicates'){
  entries=(catalogView.groups||[]).map(group=>{const picked=[...catalogView.selectedRows.values()].filter(row=>row?.groupId===group.id).length;return '<section class="catalog-candidate-group"><h3><label class="catalog-check"><input type="checkbox" data-catalog-group="'+h(group.id)+'" '+(picked>=group.total?'checked':'')+' aria-label="全選本組" aria-checked="'+(picked&&picked<group.total?'mixed':picked>=group.total?'true':'false')+'"> '+h(group.rows?.[0]?.title||'候選群組')+' · '+group.total+' 筆</label></h3><div class="actions">'+['confirm_same','different_versions','independent'].map((decision,i)=>button(['合併為同一首','同一首，但不同版本',group.total===1?'獨立為一首':'獨立為另一首'][i],'catalogGroupDecision',group.id,'tiny','data-decision="'+decision+'"')).join('')+button('關聯既有共同版本','catalogGroupLink',group.id,'tiny')+button('稍後處理','catalogLater',group.id,'tiny')+'</div>'+(group.total>8?'<details><summary>展開候選</summary>':'')+(group.rows||[]).map(rowHtml).join('')+(group.rows.length<group.total?button('載入更多候選','catalogGroupMore',group.id,'tiny'):'')+(group.total>8?'</details>':'')+'</section>';}).join('');
 }else if(status==='approved'){
  actions=button('選取本頁','relationSelectPage','','tiny')+button('取消選取','relationClear','','tiny')+button('批量加入我的歌本','relationAdd','','tiny primary',catalogView.versionSelected?.size?'':'disabled')+'<small>已選 '+(catalogView.versionSelected?.size||0)+' 首</small>';
  entries=catalogView.items.map(f=>'<section class="catalog-candidate-group catalog-family"><h3>《'+h(f.title)+'》</h3>'+(f.variants||[]).map(v=>'<div class="song catalog-variant-row"><label class="catalog-check"><input type="checkbox" data-relation-select="'+h(v.id)+'" '+(v.alreadyAdded?'disabled':catalogView.versionSelected?.has(v.id)?'checked':'')+' aria-label="選取 '+h(f.title)+' '+h(v.versionLabel||'原版')+'"></label><div class="info"><b>'+h(v.versionLabel||({cover:'翻唱',original:'原版',live:'現場版',remix:'混音版',dj:'DJ版'})[v.versionKind]||v.versionKind||'原版')+'</b><small>'+h([v.artist,v.performerDetail,v.language,v.performerType,v.versionNote].filter(Boolean).join(' · '))+'</small></div><div class="actions relation-actions">'+(isSuperAdmin()?button('編輯','relationEdit',v.id,'tiny')+button('拆版本','relationSplit',v.id,'tiny')+button('解除關係','relationUnlink',v.id,'tiny')+button('刪除','relationDelete',v.id,'tiny danger'):'')+(v.streamerCount>0&&!(v.streamerCount===1&&v.alreadyAdded)?button('查看主播（'+v.streamerCount+'）','relationRooms',v.id,'tiny'):'')+button('回報問題','catalogReport',v.id,'tiny')+(v.alreadyAdded?'<small>已在我的歌本</small>':'')+(isSuperAdmin()?button(v.hasSharedLyrics?'查看／編輯共同歌詞':'建立共同歌詞','catalogSharedLyrics',v.id,'tiny')+(v.lyricProposalCount?button('有可採用歌詞（'+v.lyricProposalCount+'）','catalogLyricProposals',v.id,'tiny'):''):'')+'</div></div>').join('')+'</section>').join('');
 }else if(status==='issues'){
  const types={song_info:'歌曲資訊',artist_name:'歌手名稱',performer_type:'歌手分類',language:'語言',version_type:'版本類型',missing_version:'缺少版本',version_relation:'版本關係',duplicate:'疑似重複',other:'其他'};
  entries=catalogView.items.map(r=>'<div class="song"><div class="info"><b>'+h(r.title)+' · '+h(types[r.issueType]||r.issueType)+'</b><small>'+h([room(r.streamerId),({pending:'待處理',processing:'處理中',fixed:'已修正',declined:'不採用'})[r.status]||r.status,time(r.createdAt)].join(' · '))+'</small><p>'+h(r.description||'')+'</p>'+(r.suggestion?'<p>建議：'+h(r.suggestion)+'</p>':'')+'</div>'+(isSuperAdmin()?'<div class="actions">'+button('處理歌曲／版本','catalogIssueOpen',r.id,'tiny')+['pending','processing','fixed','declined'].map(s=>button(({pending:'待處理',processing:'處理中',fixed:'已修正',declined:'不採用'})[s],'catalogIssueStatus',r.id,'tiny','data-status="'+s+'"')).join('')+'</div>':'')+'</div>').join('');
 }else entries=catalogView.items.map(row=>'<div class="song"><div class="info"><b>'+h(eventDescription(row,{playerName,songName:id=>song(id)?.title,roomName:room}))+'</b><small>'+h(time(row.createdAt||row.created_at))+'</small><details><summary>技術詳情</summary><pre>'+h(JSON.stringify(row,null,2))+'</pre></details></div></div>').join('');
 if(status==='duplicates'&&typeof requestAnimationFrame==='function')requestAnimationFrame(()=>{document.querySelectorAll('[data-catalog-group]').forEach(box=>{box.indeterminate=box.getAttribute('aria-checked')==='mixed';});});
 const relationFilters=status==='approved'?membershipTabs(catalogView,'catalogMembership')+'<select id="catalog-review-language" aria-label="語言篩選">'+[['','全部語言'],...(catalogView.filterOptions?.languages||[]).map(x=>[x,x])].map(([key,label])=>'<option value="'+h(key)+'" '+(catalogView.language===key?'selected':'')+'>'+h(label)+'</option>').join('')+'</select><select id="catalog-review-version" aria-label="版本篩選">'+versionOptions(catalogView.filterOptions,catalogView)+'</select>':'';
 const lyricFilter=status==='approved'?'<select id="catalog-lyrics-filter" aria-label="共同歌詞篩選">'+[['all','全部'],['with','已建立共同歌詞'],['without','未建立共同歌詞'],...(isSuperAdmin()?[['proposals','有可採用歌詞']]:[])].map(([key,label])=>'<option value="'+key+'" '+(catalogView.lyricsFilter===key?'selected':'')+'>'+label+'</option>').join('')+'</select>':'';
 const toolbar=status==='issues'?'<div class="toolbar catalog-review-toolbar"><select id="catalog-issue-filter" aria-label="問題回報狀態">'+[['pending','待處理'],['processing','處理中'],['fixed','已修正'],['declined','不採用'],['all','全部']].map(([key,label])=>'<option value="'+key+'" '+(catalogView.issueStatus===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div>':'<div class="toolbar catalog-review-toolbar"><input id="catalog-review-search" type="search" placeholder="歌名、歌手、語言、演唱類型、版本、歌詞" value="'+h(catalogView.search||'')+'">'+(['singles','duplicates'].includes(status)?'<input id="catalog-review-language" placeholder="語言篩選" value="'+h(catalogView.language||'')+'">':relationFilters+lyricFilter)+button('搜尋','catalogFilter')+(['singles','duplicates'].includes(status)?button('選取本頁','catalogSelectPage')+button('選取目前搜尋結果','catalogSelectAll')+button('取消選取','catalogClear')+'<small>已選 '+catalogView.selected.size+' 筆</small>':'')+'</div>';
 return tabs+toolbar+'<div class="actions catalog-batch-actions">'+actions+'</div>'+(catalogView.error?'<p class="error">'+h(catalogView.error)+'</p>':'')+(status==='approved'?sortControl('catalog'):'')+'<div id="catalog-review-list">'+(entries||blank(catalogView.loading?'正在讀取…':'沒有待處理資料'))+'</div>'+catalogPager(catalogView,'catalogPage');
}
async function scanCatalogCandidates(){
 if(!isSuperAdmin()||catalogView.scanning)return;
 if(demo||draft)return toast('預覽模式不會掃描正式歌本');
 if(catalogView.scanComplete){catalogView.scanCursor='';catalogView.scanTotal=0;catalogView.scanComplete=false;}
 catalogView.scanning=true;render();
 try{const r=await api({op:'catalogScan',afterSongId:catalogView.scanCursor,limit:100,management:true});
  catalogView.scanTotal+=Number(r.processed)||0;catalogView.scanCursor=r.nextCursor||'';catalogView.scanComplete=!r.nextCursor;
  catalogView.loaded=false;await loadCatalogReview();toast(catalogView.scanComplete?'候選掃描完成，等待總裁審核':'本批候選已完成，可繼續掃描下一批');
 }catch(err){toast(err.message);}finally{catalogView.scanning=false;if(['catalog','settings'].includes(tab))render();}
}
function catalogTemplateHtml(){
 const data=catalogView.templates;if(!data)return `<p>${catalogView.loading?'正在讀取模板…':h(catalogView.error||'尚未載入模板')}</p>`;
 return [['language','語言',data.languages||[]],['performerType','演唱者類型',data.performerTypes||[]]].map(([kind,label,rows])=>`<h3>${label}</h3><div class="actions">${button('新增'+label,'catalogTemplateAdd',kind)}</div>${rows.map(row=>`<div class="song"><div class="info"><b>${h(row.name)}</b><small>${row.active===false?'已停用':'使用中'}</small></div>${button('編輯','catalogTemplateEdit',row.id,'tiny',`data-kind="${kind}"`)}</div>`).join('')||blank()}`).join('');
}
async function loadCatalogReview(){
 if(!admin||tab!=='catalog'||catalogView.loading)return;
 if(catalogView.section==='confirmed'){catalogView.loaded=true;render();return;}
 if(demo||draft){catalogView.error='預覽模式不會寫入正式共同曲庫';catalogView.loaded=true;render();return;}
 catalogView.loading=true;catalogView.error='';
 const section=catalogView.section,page=catalogView.page,size=catalogView.pageSize||20,query=catalogView.search||'',language=catalogView.language||'',versionKind=catalogView.versionKind||'',versionLabel=catalogView.versionLabel||'',membership=catalogView.membership,sort=catalogView.sort,lyricsFilter=catalogView.lyricsFilter||'all',streamerId=state.currentStreamer?.id;
 const current=()=>!!admin&&tab==='catalog'&&catalogView.section===section&&catalogView.page===page&&(catalogView.pageSize||20)===size&&(catalogView.search||'')===query&&(catalogView.language||'')===language&&(catalogView.versionKind||'')===versionKind&&(catalogView.versionLabel||'')===versionLabel&&catalogView.membership===membership&&catalogView.sort===sort&&(catalogView.lyricsFilter||'all')===lyricsFilter&&state.currentStreamer?.id===streamerId;
 try{const response=section==='templates'?await api({op:'catalogTemplates',management:true}):await api({op:section==='issues'?'catalogIssues':'catalogReviewList',status:section==='approved'?'families':section==='issues'?catalogView.issueStatus:section,limit:size,offset:page*size,q:query,language,versionKind,versionLabel,membership,sort,lyricsFilter,management:true});
  if(!current())return;
  if(section==='approved')catalogView.filterOptions=response.filters||{};
  if(section==='templates')catalogView.templates=response;
  else{catalogView.groups=section==='duplicates'?response.items||[]:[];catalogView.items=section==='duplicates'?catalogView.groups.flatMap(g=>g.rows||[]):response.items||[];catalogView.counts=response.counts||catalogView.counts;catalogView.total=response.total||0;catalogView.hasMore=!!response.hasMore;}
  catalogView.loaded=true;
 }catch(err){if(current()){catalogView.error=err.message;catalogView.loaded=true;}}finally{catalogView.loading=false;if(tab==='catalog')render();}
}
async function catalogReviewAction(decision,ids=[...catalogView.selected],target={}){
 if(!isSuperAdmin()||!ids.length)return toast('請先選擇待審歌曲');
 if(ids.length>50)return toast('一次請選最多 50 筆，確保整批在同一交易完成');
 if(demo||draft)throw Error('請在正式管理端審核');
 const expectedSources=Object.fromEntries(ids.map(id=>[id,catalogView.selectedSources.get(id)]));
 if(Object.values(expectedSources).some(v=>!v))throw Error('候選資料已更新，請重新選取');
 const {confirmation,...payload}=target;
 if(!confirm(confirmation||'只處理已選 '+ids.length+' 筆？原歌本、私有設定與自訂歌詞保留。'))return;
 await api({op:'catalogReview',decision,candidateIds:ids,expectedSources,...payload,management:true});
 for(const id of ids){catalogView.selected.delete(id);catalogView.selectedRows.delete(id);catalogView.selectedSources.delete(id);catalogView.selectedVariants.delete(id);}
 invalidateCatalogTabs();await loadCatalogReview();toast('已完成 '+ids.length+' 筆審核');
}
async function openSharedBrowse(reviewIds=null,linkSongId=null){
 if(!isAdmin())return;
 sharedBrowse.relationSelection=false;sharedBrowse.membership='missing';sharedBrowse.membershipViews.clear();sharedBrowse.versionKind='';sharedBrowse.versionLabel='';clearTimeout(catalogBrowseTimer);
 sharedBrowse.reviewIds=Array.isArray(reviewIds)&&reviewIds.length?reviewIds:null;sharedBrowse.linkSongId=linkSongId;sharedBrowse.addMode=tab==='songs'&&!sharedBrowse.reviewIds&&!linkSongId;if(sharedBrowse.addMode||linkSongId)sharedBrowse.inactive=false;
 sharedBrowse.selected.clear();sharedBrowse.selectedRows.clear();sharedBrowse.q='';sharedBrowse.language='';sharedBrowse.performerType='';sharedBrowse.searchMode='metadata';sharedBrowse.page=0;sharedBrowse.items=[];sharedBrowse.suggestions=[];sharedBrowse.error='';
 const languages=await catalogTemplateChoices('languages','',['華語','台語','粵語','英文','日文','韓文','其他']),types=await catalogTemplateChoices('performerTypes','',['女歌手','男歌手','團體','合唱','其他']);
 modal(sharedBrowse.reviewIds?'同一首：選擇現有歌曲或不同版本':'從共同曲庫選歌',`<p class="muted">由伺服器搜尋並分頁，只下載目前頁面的歌曲資料。</p><div id="catalog-suggestions"></div><div class="catalog-browse-filters catalog-browse-toolbar"><input type="search" id="catalog-browse-q" value="" placeholder="搜尋歌名或歌手" aria-label="搜尋共同曲庫"><select id="catalog-browse-mode" aria-label="搜尋範圍"><option value="metadata">歌名／歌手</option><option value="lyrics">共同歌詞</option></select><select id="catalog-browse-language" aria-label="語言篩選"><option value="">所有語言</option>${languages.map(v=>'<option value="'+h(v)+'">'+h(v)+'</option>').join('')}</select><select id="catalog-browse-performer" aria-label="歌手類型篩選"><option value="">所有歌手類型</option>${types.map(v=>'<option value="'+h(v)+'">'+h(v)+'</option>').join('')}</select></div><div id="catalog-browse-list" aria-live="polite">${blank('讀取中…')}</div>`);
 if(sharedBrowse.reviewIds?.length===1)loadCatalogSuggestions(sharedBrowse.reviewIds[0]);
 await loadSharedBrowse(0);
}
async function loadCatalogSuggestions(candidateId){
 try{const rows=await api({op:'catalogSuggestions',candidateId,management:true});if(sharedBrowse.reviewIds?.[0]!==candidateId||!$('#catalog-suggestions'))return;
  sharedBrowse.suggestions=rows||[];$('#catalog-suggestions').innerHTML=rows.length?'<h3>可能相同的共同歌曲（僅供參考，不會自動合併）</h3>'+rows.map(row=>'<div class="song"><div class="info"><b>'+h(row.title)+' · '+h(row.artist)+'</b><small>'+h([row.versionLabel,row.language,row.performerType].filter(Boolean).join(' · '))+'</small></div><div class="actions">'+button('同一版本','catalogSuggestionTarget',row.variantId,'tiny','data-mode="link_variant"')+button('不同版本','catalogSuggestionTarget',row.variantId,'tiny','data-mode="create_variant"')+'</div></div>').join(''):'';
 }catch{const holder=$('#catalog-suggestions');if(holder)holder.textContent='可在下方搜尋共同歌曲。';}
}
