async function loadSharedBrowse(page=0){
 if(!$('#catalog-browse-list'))return;
 const generation=++sharedBrowse.generation;sharedBrowse.page=Math.max(0,page);sharedBrowse.loading=true;sharedBrowse.error='';renderSharedBrowse();
 if(demo||draft){sharedBrowse.loading=false;sharedBrowse.error='預覽模式無共同曲庫；可照常編輯本主播歌曲';renderSharedBrowse();return;}
 try{const r=await api({op:'catalogSearch',q:sharedBrowse.q.trim(),language:sharedBrowse.language,performerType:sharedBrowse.performerType,searchMode:sharedBrowse.searchMode,membership:sharedBrowse.membership,sort:sharedBrowse.sort,versionKind:sharedBrowse.versionKind,versionLabel:sharedBrowse.versionLabel,...(sharedBrowse.inactive?{inactive:true}:{}),limit:sharedBrowse.pageSize||20,offset:sharedBrowse.page*(sharedBrowse.pageSize||20),management:true});if(generation!==sharedBrowse.generation)return;
  sharedBrowse.items=r.items||[];sharedBrowse.total=r.total||0;sharedBrowse.hasMore=!!r.hasMore;sharedBrowse.filterOptions=r.filters||sharedBrowse.filterOptions;
 }catch(err){if(generation!==sharedBrowse.generation)return;sharedBrowse.error=err.message;sharedBrowse.items=[];}
 finally{if(generation===sharedBrowse.generation){sharedBrowse.loading=false;renderSharedBrowse();}}
}
