document.addEventListener('change',e=>{const key=({'catalog-browse-mode':'searchMode','catalog-browse-language':'language','catalog-browse-performer':'performerType'})[e.target.id];if(!key)return;sharedBrowse[key]=e.target.value;sharedBrowse.selected.clear();sharedBrowse.selectedRows.clear();sharedBrowse.membershipViews.clear();sharedBrowse.page=0;sharedBrowse.generation++;clearTimeout(catalogBrowseTimer);loadSharedBrowse(0).catch(err=>toast(err.message));});
