function catalogPager(view,act){const size=view.pageSize||20,total=Math.max(1,Math.ceil((view.total||0)/size));return '<div class="pagination">'+button('第一頁',act,'first','tiny',view.page?'':'disabled')+button('上一頁',act,'-1','tiny',view.page?'':'disabled')+'<label>頁碼<input type="number" min="1" max="'+total+'" value="'+(view.page+1)+'" data-catalog-page="'+act+'"></label><span>共 '+total+' 頁 · '+(view.total||0)+' 筆</span>'+button('下一頁',act,'1','tiny',view.hasMore?'':'disabled')+button('最後一頁',act,'last','tiny',view.hasMore?'':'disabled')+'<label>每頁<select data-catalog-size="'+act+'">'+[10,20,50].map(n=>'<option '+(n===size?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div>';}
function selectCatalogRows(rows){for(const row of rows){const id=String(row.candidateId||row.id);catalogView.selected.add(id);catalogView.selectedRows.set(id,row);catalogView.selectedSources.set(id,row.sourceHash);catalogView.selectedVariants.set(id,{variantId:row.variantId,updatedAt:row.variantUpdatedAt});}}
async function fetchCatalogGroupRows(group){const rows=[...(group.rows||[])];while(rows.length<group.total){if(rows.length>10000)throw Error('這組候選過大，請縮小範圍後選取');const r=await api({op:'catalogReviewList',status:'duplicates',groupId:group.id,limit:50,offset:rows.length,management:true});if(!r.items?.length)break;rows.push(...r.items.map(row=>({...row,groupId:group.id})));if(!r.hasMore)break;}return rows;}
async function selectAllCatalog(){if(!['singles','duplicates'].includes(catalogView.section))return;const section=catalogView.section,q=catalogView.search||'',language=catalogView.language||'';catalogView.loading=true;try{for(let offset=0;offset<catalogView.total;offset+=50){const r=await api({op:'catalogReviewList',status:section,q,language,limit:50,offset,management:true});if(section!==catalogView.section||q!==(catalogView.search||'')||language!==(catalogView.language||''))return;if(section==='duplicates')for(const group of r.items||[])selectCatalogRows(await fetchCatalogGroupRows(group));else selectCatalogRows(r.items||[]);if(!r.hasMore)break;}toast('已選 '+catalogView.selected.size+' 筆；一次審核最多 50 筆');}finally{catalogView.loading=false;render();}}
async function confirmSameCatalog(groupId){await selectedGroupDecision(groupId,'confirm_same');}
async function deactivateSharedSongs(){const rows=[...sharedBrowse.selected].map(id=>sharedBrowse.selectedRows.get(id)).filter(Boolean);if(!rows.length)return;if(!confirm('停用 '+rows.length+' 筆共同歌曲？相關主播原歌本與歷史都保留，之後可重新啟用。'))return;for(const row of rows){const id=String(row.variantId||row.id);await api({op:'catalogGovernance',action:'update_variant',variantIds:[id],metadata:{active:false},expectedVersions:catalogVersions([row]),management:true});sharedBrowse.selected.delete(id);sharedBrowse.selectedRows.delete(id);}await loadSharedBrowse(0);toast('共同歌曲已停用，主播原歌本仍保留');}
function drawForStreamer(){const picker=$('#dialog [name=songId]');if(!picker)return;const eligible=state.songs.filter(s=>(!s.streamer_id||s.streamer_id===state.currentStreamer.id)&&!s.hidden&&s.active!==false&&!s.disabled&&s.available!==false);const selectedTags=[...($('#proxy-fate-category')?.querySelectorAll('[data-proxy-draw-tag]:checked')||[])].map(x=>x.value);const result=drawSong(eligible,selectedTags,drawnStreamerSong?[drawnStreamerSong]:[],drawnStreamerSong);if(!result.song)return toast('目前沒有可抽的歌曲');drawnStreamerSong=result.song.songId;const form=picker.closest('form'),self=form?.querySelector('[name=selfProvided]');if(self){self.checked=true;form.dataset.requestSource='proxy_draw';}picker.value=drawnStreamerSong;const box=picker.closest('.entity-picker');if(box){box.querySelector('[data-entity-query]').value=result.song.title+'－'+result.song.artist;box.querySelector('.entity-results').innerHTML='';}picker.dispatchEvent(new Event('change',{bubbles:true}));toast('抽到《'+result.song.title+'》－'+result.song.artist);}


