async function selectAllShared(){const q=sharedBrowse.q,inactive=sharedBrowse.inactive,g=sharedBrowse.generation,language=sharedBrowse.language,performerType=sharedBrowse.performerType,searchMode=sharedBrowse.searchMode;for(let offset=0;offset<sharedBrowse.total;offset+=50){const r=await api({op:'catalogSearch',q,language,performerType,searchMode,membership:sharedBrowse.membership,sort:sharedBrowse.sort,versionKind:sharedBrowse.versionKind,versionLabel:sharedBrowse.versionLabel,...(inactive?{inactive:true}:{}),limit:50,offset,management:true});if(q!==sharedBrowse.q||inactive!==sharedBrowse.inactive||g!==sharedBrowse.generation)return;for(const row of r.items||[]){const id=String(row.variantId||row.id);if(!row.alreadyAdded||isSuperAdmin()&&!sharedBrowse.addMode){sharedBrowse.selected.add(id);sharedBrowse.selectedRows.set(id,row);}}if(!r.hasMore)break;}renderSharedBrowse();}
async function mergeSameVersions(){const rows=[...sharedBrowse.selected].map(id=>sharedBrowse.selectedRows.get(id));if(rows.length<2||rows.length>50||rows.some(r=>!r||r.active===false))return toast('請選 2～50 個使用中的同版本共同歌曲');const ids=rows.map(r=>String(r.variantId||r.id));modal('確認是同一首、同一版本',nativeSelect('targetVariant','保留哪筆共同資料與共同歌詞',rows.map((r,i)=>[ids[i],[r.title,r.artist,r.language,r.versionLabel].filter(Boolean).join(' · ')]),ids[0])+'<p>會將 '+rows.length+' 筆共同歌曲整成 1 筆使用中的主檔，主播原歌本、標籤、Key、自訂歌詞及私人註記保留。使用共同歌詞的歌曲會跟隨所選主檔；其他共同版本停用並保留歷史。</p>',async f=>{if(!confirm('確認整併 '+rows.length+' 筆共同歌曲？相關主播原歌本都保留。'))return;await api({op:'catalogMergeSame',variantIds:ids,targetVariant:f.get('targetVariant'),expectedVersions:catalogVersions(rows),management:true});sharedBrowse.selected.clear();sharedBrowse.selectedRows.clear();await refresh(true);toast('已確認為同一筆共同歌曲');});}

async function relationAction(action,id){
 const row=catalogView.items.flatMap(f=>f.variants||[f]).find(x=>String(x.id)===id);if(!row?.variantId)return;
 sharedBrowse.items=[row];
 if(action==='relationEdit')return editCatalogMetadata(row.variantId);
 if(action==='relationDelete'){sharedBrowse.selected=new Set([id]);sharedBrowse.selectedRows=new Map([[id,row]]);await deactivateSharedSongs();invalidateCatalogTabs();return render();}
 const response=await api({op:'catalogRooms',variantId:row.variantId,limit:50,offset:0,management:true});
 const songs=(response.items||[]).flatMap(room=>(room.songs||[]).map(s=>({...s,streamerId:room.streamerId})));
 if(action==='relationRooms')return modal('使用此共同版本的主播',relationRoomRows(response,id));
 modal(action==='relationSplit'?'拆為另一版本':'解除共同關係',songs.map(x=>check('sources',(state.streamers.find(z=>z.id===x.streamerId)?.display_name||x.streamerId)+' · '+x.title+'－'+x.artist,false).replace('name="sources"','name="sources" value="'+h(x.candidateId||'')+'"'+(x.candidateId?'':' disabled'))).join('')+(action==='relationSplit'?field('versionLabel','新版本名稱','','text','required maxlength="120"'):'')+(response.hasMore?'<p>目前顯示前 50 位主播；可分批處理，原關係仍保留。</p>':''),async f=>{
  const ids=f.getAll('sources');if(!ids.length)throw Error('請選擇主播來源');const selected=songs.filter(x=>ids.includes(x.candidateId));
  if(action==='relationSplit')await api({op:'catalogGovernance',action:'split_variant',variantIds:[id],candidateIds:ids,expectedSources:Object.fromEntries(selected.map(x=>[x.candidateId,x.sourceHash])),expectedVersions:catalogVersions([row]),metadata:{versionLabel:f.get('versionLabel')},management:true});
  else await api({op:'catalogReview',decision:'unlink',candidateIds:ids,expectedSources:Object.fromEntries(selected.map(x=>[x.candidateId,x.sourceHash])),management:true});
  invalidateCatalogTabs();await loadCatalogReview();toast('關係已更新，主播原資料保留');
 });
}
function relationRoomRows(response,variantId,offset=0){return (response.items||[]).map(room=>'<div class="song"><div class="info"><b>'+h(room.streamerName||state.streamers.find(z=>z.id===room.streamerId)?.display_name||'未命名主播')+'</b>'+(room.songs||[]).map(s=>'<small>'+h(s.title+'－'+s.artist)+'</small>').join('')+'</div>'+(isSuperAdmin()?(room.songs||[]).map(s=>button('移到同歌曲其他版本','relationMove',s.songId,'tiny','data-streamer="'+h(room.streamerId)+'" data-variant="'+h(variantId)+'" data-source="'+h(s.sourceHash)+'"')).join(''):'')+'</div>').join('')+'<div class="pagination" data-total-pages="'+Math.max(1,Math.ceil(response.total/50))+'">'+button('上一頁','relationRoomsPage',variantId,'tiny',`data-offset="${Math.max(0,offset-50)}" ${offset?'':'disabled'}`)+'<small>第 '+(Math.floor(offset/50)+1)+' 頁</small>'+button('下一頁','relationRoomsPage',variantId,'tiny',`data-offset="${offset+50}" ${response.hasMore?'':'disabled'}`)+'</div>'||blank();}
async function relationRoomsPage(id,offset){const r=await api({op:'catalogRooms',variantId:id,limit:50,offset,management:true});modal('使用此共同版本的主播',relationRoomRows(r,id,offset));}
function moveRelation(songId,sourceVariant,streamerId,sourceHash){if(!isSuperAdmin())return;const family=catalogView.items.find(f=>f.variants?.some(v=>v.id===sourceVariant));if(!family)return;const options=family.variants.filter(v=>v.id!==sourceVariant);if(!options.length)return toast('這首共同歌曲目前沒有其他版本');modal('移動歌曲版本',nativeSelect('variantId','移到版本',options.map(v=>[v.id,[v.versionLabel||'原版',v.artist,v.performerDetail].filter(Boolean).join(' · ')]),options[0].id)+'<p>只改共同版本關聯；主播原歌、演唱歷史與私人資料都保留。</p>',async f=>{await api({op:'catalogLinkSong',streamer:streamerId,songId,variantId:f.get('variantId'),expectedSource:sourceHash,expectedVariant:sourceVariant,sameFamilyOnly:true,management:true});invalidateCatalogTabs();await loadCatalogReview();toast('版本已移動');});}

