 const saved=catalogTabStates.get(section)||{page:0,pageSize:20,items:[],groups:[],total:0,hasMore:false,loaded:false,search:'',language:'',versionKind:'',filterOptions:{},versionSelected:new Set(),versionRows:new Map(),lyricsFilter:'all',issueStatus:'pending',error:'',selected:new Set(),selectedRows:new Map(),selectedSources:new Map(),selectedVariants:new Map()};
