function installSongAutocomplete(){
 const form=$('#modal-form'),input=form.querySelector('[name=title]'),box=$('#song-catalog-candidates');let timer,closed=false,membership='missing';
 const scope=()=>JSON.stringify([admin?.accountId,admin?.role,admin?.streamer_id,admin?.spaceId,state.currentStreamer?.spaceId,state.currentStreamer?.id,streamerSlug,!!demo,!!draft]),identity=scope(),current=()=>!closed&&form.isConnected&&identity===scope();
 const models=Object.fromEntries(['missing','added'].map(key=>[key,{q:'',page:0,rows:[],total:0,loaded:false,loading:false,error:'',generation:0}]));
 form.querySelector('[type=submit]').textContent='新增為全新歌曲';
 const label=input.closest('label'),row=document.createElement('div');row.className='full song-title-row';label.replaceWith(row);row.append(label);row.insertAdjacentHTML('beforeend','<div class="song-title-actions">'+button('從共同曲庫選歌（批量）','catalogBrowse','','tiny')+'<small>輸入至少 2 個字，搜尋共同曲庫。</small></div>');
 const render=()=>{if(!current())return;const view=models[membership],pages=Math.max(1,Math.ceil(view.total/10));
  const tabs='<div class="catalog-membership-tabs">'+[['missing','尚未加入'],['added','已在我的歌本']].map(([key,text])=>'<button type="button" data-song-catalog-membership="'+key+'" class="tiny '+(membership===key?'active':'')+'">'+text+'</button>').join('')+'</div>';
  const rows=view.loading?'<small>搜尋中…</small>':view.error?'<small class="error">'+h(view.error)+'</small><button type="button" data-song-catalog-retry>重新讀取</button>':view.rows.map(r=>'<div class="song"><div class="info"><b>'+h(r.title)+'</b><small>'+h([r.artist,r.language,r.performerType,r.versionLabel||'原版'].filter(Boolean).join(' · '))+'</small></div><div class="actions"><button type="button" data-add-variant="'+h(r.variantId)+'" '+(r.alreadyAdded?'disabled':'')+'>'+(r.alreadyAdded?'已在我的歌本':'加入我的歌本')+'</button><button type="button" data-new-version="'+h(r.variantId)+'">這是同一首，但我的版本不同</button></div></div>').join('')||'<small>沒有符合的共同歌曲，可新增為全新歌曲。</small>';
  box.innerHTML=tabs+rows+'<div class="pagination"><button type="button" data-song-catalog-page="'+(view.page-1)+'" '+(!view.page||view.loading?'disabled':'')+'>上一頁</button><small>第 '+(view.page+1)+' 頁 · 共 '+view.total+' 首</small><label>跳至第 <input type="number" data-song-catalog-jump min="1" max="'+pages+'" value="'+(view.page+1)+'" aria-label="共同曲庫候選頁碼" '+(view.loading?'disabled':'')+'> 頁</label><button type="button" data-song-catalog-page="'+(view.page+1)+'" '+((view.page+1)*10>=view.total||view.loading?'disabled':'')+'>下一頁</button></div>';
 };
 const read=async(key,page,force=false)=>{if(!current()||!['missing','added'].includes(key))return;const view=models[key],q=input.value.trim();if(q.length<2)return;clearTimeout(timer);
  page=Math.max(0,page);if(view.loaded&&view.q===q&&view.page===page&&!force){render();return;}
  const generation=++view.generation;view.q=q;view.page=page;view.loading=true;view.error='';view.loaded=false;render();
  try{const result=await api({op:'catalogSearch',q,membership:key,limit:10,offset:page*10,management:true});if(!current()||generation!==view.generation||input.value.trim()!==q)return;
   if(!Array.isArray(result.items)||result.items.length>10||!Number.isSafeInteger(result.total)||result.total<result.items.length||result.items.some(r=>!r||typeof(r.variantId||r.id)!=='string'||!(r.variantId||r.id)))throw Error('共同曲庫搜尋資料不正確');
   view.rows=result.items.map(r=>({...r,variantId:r.variantId||r.id}));view.total=result.total;view.loaded=true;
  }catch(err){if(current()&&generation===view.generation&&input.value.trim()===q){view.error=err.message;view.rows=[];}}
  finally{if(current()&&generation===view.generation){view.loading=false;if(membership===key)render();}}
 };
 const cleanup=()=>{closed=true;clearTimeout(timer);for(const view of Object.values(models))view.generation++;};$('#dialog').addEventListener('close',cleanup,{once:true});
 const schedule=()=>{if(!current())return;clearTimeout(timer);const q=input.value.trim();form.querySelector('[name=catalogCandidateFamily]').value='';form.querySelector('[type=submit]').textContent='新增為全新歌曲';for(const view of Object.values(models)){view.generation++;view.q=q;view.page=0;view.rows=[];view.total=0;view.loaded=false;view.loading=false;view.error='';}if(q.length<2){box.innerHTML='';return;}render();timer=setTimeout(()=>read(membership,0),400);};
 input.addEventListener('input',e=>{if(!e.isComposing)schedule();});input.addEventListener('compositionend',schedule);
 box.onclick=async e=>{const b=e.target.closest('[data-song-catalog-membership],[data-song-catalog-page],[data-song-catalog-retry],[data-add-variant],[data-new-version]');if(!b||b.disabled||!current())return;
  if(b.dataset.songCatalogMembership){const key=b.dataset.songCatalogMembership;if(!models[key])return;membership=key;render();return read(membership,models[membership].page);}
  if(b.hasAttribute('data-song-catalog-page')){const page=Number(b.dataset.songCatalogPage);if(Number.isSafeInteger(page)&&page>=0&&page<Math.max(1,Math.ceil(models[membership].total/10)))return read(membership,page);return;}
  if(b.hasAttribute('data-song-catalog-retry'))return read(membership,models[membership].page,true);
  const view=models[membership],chosen=view.rows.find(r=>r.variantId===(b.dataset.addVariant||b.dataset.newVersion));if(!chosen||view.loading||view.q!==input.value.trim())return;
  if(b.dataset.addVariant){if(chosen.alreadyAdded)return;b.disabled=true;try{await api({op:'catalogBatchAdd',variantIds:[chosen.variantId],lyricsMode:'shared',management:true});if(!current())return;const savedDraft=proxyDraft;if(savedDraft)savedDraft.created=true;invalidateCatalogTabs();$('#dialog').close();await refresh(true);if(identity!==scope())return;if(savedDraft){proxyDraft=null;onBehalf();installProxyNewButton();restoreProxyDraft(savedDraft,state.songs.find(s=>s.catalogVariantId===chosen.variantId)?.songId);}toast('已加入我的歌本');}catch(err){if(current()){b.disabled=false;toast(err.message);}}return;}
  for(const [key,value] of Object.entries({title:chosen.title,artist:chosen.artist,cat:chosen.language,artistType:chosen.performerType,catalogCandidateFamily:chosen.familyId})){const x=form.querySelector('[name='+key+']');if(x)x.value=value;}
  form.querySelector('[name=version]').focus();form.querySelector('[type=submit]').textContent='送審：同一首、不同版本';box.innerHTML='<p>已指定《'+h(chosen.title)+'》作品，請填入你的版本；尚未建立正式共同版本。</p>';
 };
 const jump=target=>{if(!target.hasAttribute('data-song-catalog-jump')||!current())return;const page=Number(target.value)-1,max=Math.max(0,Math.ceil(models[membership].total/10)-1);if(Number.isSafeInteger(page)&&page>=0)read(membership,Math.min(page,max));};
 box.addEventListener('change',e=>jump(e.target));box.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&e.target.hasAttribute('data-song-catalog-jump')){e.preventDefault();e.stopPropagation();jump(e.target);}});
}
