 const history=table==='queue'&&!['pending','waiting'].includes(row.status);
 const fields=history?['effective_at']:({queue:['at'],ledger:['at'],crowns:['activatedAt','expiresAt'],cards:['startsAt','expiresAt'],wishes:['at']}[table]||[]).filter(key=>row[key]||key==='at');
