async function setListSort(key,value){
 if(!Object.hasOwn(listSorts,key)||!['newest','oldest'].includes(value)||listSorts[key]===value)return;
 listSorts[key]=value;
 for(const control of document.querySelectorAll('[data-list-sort]'))if(control.dataset.listSort===key&&control.dataset.sort){const active=control.dataset.sort===value;control.classList.toggle('active',active);control.setAttribute('aria-pressed',String(active));}
 if(key==='catalog'){catalogView.sort=value;catalogView.page=0;catalogView.membershipViews.clear();catalogView.loaded=false;render();}
 else if(key==='shared'){sharedBrowse.sort=value;sharedBrowse.membershipViews.clear();await loadSharedBrowse(0);}
 else if(key==='players'){playerManagement.setSort(value);await loadPlayerManagement();}
 else if(key==='common'){commonBook.sort=value;await loadCommonBook(0);}
 else {pages[key==='queueCurrent'?'queue':key==='queueHistory'?'queue-history':key]=1;roomSearch.generation++;roomSearch.pendingKey=null;render();}
}
