  if(identity!==favoritesIdentity()||identity!==favoriteSelectionIdentity)throw Error('登入或主播已變更，請重新選取');if(state.revision!==visibleRevision)throw Error('歌曲或價格已更新，請重新開啟確認視窗');if(kind==='live'&&!f.has('gift'))throw Error('請確認現點的禮物方式');
