  lines.push(room?.name||item.streamer);
  for(const q of item.quotes){if(!Number.isFinite(q.creditCost)||q.creditCost<=0||q.kind==='live'&&(!Number.isFinite(q.price)||!Number.isFinite(q.double)))throw Error('點歌金額資料不正確');lines.push(q.title+'：'+(q.kind==='live'?'給歌手 '+money(q.price)+'＋雙費 '+money(q.double)+'（不占提歌名額）':'使用 '+q.creditCost+' 首存歌及提歌額度'));}
